/* lore/pt.lore.js — descriptions for the "Описание созвездий" tab (core/lore.js). v618 (owner): written in English first,
   from English-language sources (official books as summarised by the English wikis), in our own words; the other six
   languages are translated from the English. Loaded only when the tab is opened. */
KC.addLore("pt", {
  "dnd.c.artificer": "O Artífice é um inventor que trata a magia como um ofício, canalizando magias por meio de ferramentas e engenhocas em vez de preces ou tomos antigos. Artífices infundem objetos comuns com propriedades mágicas e conseguem consertar, aprimorar e improvisar dispositivos na hora. A classe tem raízes no mundo de Eberron e também aparece no Caldeirão de Tasha para Tudo.",
  "dnd.c.barbarian": "O Bárbaro é um guerreiro feroz movido por uma fúria primitiva. Em combate ele entra em Fúria, que torna seus golpes mais fortes e o ajuda a suportar danos físicos, e luta melhor com armadura leve ou sem armadura, confiando em sua resistência e instinto. Muitos vêm das margens selvagens da civilização, mas qualquer fonte profunda de raiva pode alimentar esse dom.",
  "dnd.c.bard": "O Bardo faz magia com música, palavras e performance, num mundo que, segundo dizem, foi criado pela palavra. Bardos fortalecem aliados com a Inspiração de Bardo, sabem um pouco de quase tudo e dominam uma ampla gama de magias de encantamento, cura e trapaça. Eles se reúnem em colégios informais que compartilham histórias e técnicas.",
  "dnd.c.cleric": "O Clérigo é um campeão sacerdotal que empunha magia divina concedida por um deus ou poder superior. Clérigos curam e protegem seus companheiros, afastam mortos-vivos e invocam o poder de sua divindade com Canalizar Divindade. Cada um serve a um domínio divino que molda suas magias e dons.",
  "dnd.c.druid": "O Druida é um guardião do mundo natural que tira seu poder da própria natureza ou de divindades da natureza. Com a Forma Selvagem, druidas assumem a forma de animais, e suas magias invocam tempestades, curam ferimentos e comandam plantas e feras. Eles se reúnem em círculos que compartilham uma visão particular do poder da natureza.",
  "dnd.c.fighter": "O Guerreiro é um mestre das armas e armaduras, treinado para se destacar em todo tipo de combate. Guerreiros fazem ataques extras, superam seus limites com Surto de Ação e recuperam o fôlego com Retomar o Fôlego. Soldados, mercenários, cavaleiros e duelistas cabem nesta classe.",
  "dnd.c.monk": "O Monge é um artista marcial que canaliza sua energia interior, chamada ki (Foco nas regras de 2024), em feitos extraordinários. Monges golpeiam com os punhos e armas simples numa velocidade estonteante, desviam projéteis e se movem mais rápido que pessoas comuns. Seu treinamento vem de mosteiros que seguem tradições distintas.",
  "dnd.c.paladin": "O Paladino é um guerreiro sagrado ligado a um juramento solene, a verdadeira fonte de seu poder. Paladinos combinam combate com armadura e magia divina, curando com Cura pelas Mãos e carregando seus golpes de energia radiante com a Destruição Divina. É o juramento, e não um templo, que define os ideais pelos quais lutam.",
  "dnd.c.ranger": "O Patrulheiro é um caçador e batedor das terras selvagens que combina habilidade marcial com magia da natureza. Patrulheiros se destacam em rastrear, sobreviver na natureza e lutar com arco ou lâmina, e muitas vezes estudam inimigos e terrenos específicos. Eles guardam as fronteiras entre a civilização e os perigos além dela.",
  "dnd.c.rogue": "O Ladino confia em perícia, furtividade e precisão em vez de força bruta. Ladinos desferem um Ataque Furtivo devastador quando pegam um inimigo desprevenido, escapam com a Ação Ardilosa e dominam uma grande variedade de perícias, de abrir fechaduras a se livrar de encrencas na conversa. Ladrões, espiões, batedores e assassinos fazem parte da classe.",
  "dnd.c.sorcerer": "O Feiticeiro carrega a magia no próprio ser, muitas vezes por uma linhagem ou por um evento extraordinário. Em vez de estudar magias, ele canaliza um poder inato e o molda com Metamágica, gastando pontos de feitiçaria para alterar, estender ou acelerar suas magias. A origem de seu poder determina seus dons especiais.",
  "dnd.c.warlock": "O Bruxo obtém magia por meio de um pacto com um poderoso patrono de outro mundo. Bruxos têm poucos espaços de magia, que voltam após um descanso curto, truques característicos como a Rajada Mística e Invocações Místicas que concedem habilidades incomuns. A natureza do patrono influencia tanto seus poderes quanto sua personalidade.",
  "dnd.c.wizard": "O Mago é um conjurador estudioso que domina a magia por meio do estudo e registra suas magias em um grimório. Com a lista de magias mais ampla de todas as classes, ele pode preparar a magia certa para quase qualquer situação e recuperar parte da magia gasta com a Recuperação Arcana. Muitos se especializam em uma única escola de magia.",
  "dnd.s.artificer.alchemist": "O Alquimista é um artífice especializado em misturar preparados poderosos. Ele cria elixires experimentais com efeitos úteis imprevisíveis, como cura, voo ou resiliência, e usa seu saber alquímico para fortalecer suas curas e suas magias de ácido e fogo. Mais tarde, consegue curar males e restaurar grandes quantidades de vitalidade.",
  "dnd.s.artificer.armorer": "O Armeiro é um artífice que transforma uma armadura numa segunda pele mágica. Sua armadura arcana pode ser ajustada para o modelo Guardião, com manoplas trovejantes e um campo protetor, ou para o modelo Infiltrador, com um lançador de relâmpagos e furtividade aprimorada. Conforme avança, a armadura comporta mais infusões e fica mais poderosa.",
  "dnd.s.artificer.artillerist": "O Artilheiro é um artífice especializado em magia explosiva e destrutiva. Sua criação característica é o canhão místico, uma pequena torre mágica que pode queimar inimigos com fogo, arremessá-los com força ou proteger aliados. Ele também canaliza magias por uma arma de fogo arcana para causar mais dano.",
  "dnd.s.artificer.battlesmith": "O Ferreiro de Batalha é um artífice que combina proeza em combate com reparo e proteção. Ele constrói um defensor de aço, um leal companheiro mecânico que luta ao seu lado, e pode usar sua Inteligência para atacar com armas mágicas. Sua magia tende à cura e à proteção dos aliados.",
  "dnd.s.barbarian.beast": "O Caminho da Fera é um caminho de bárbaro cuja fúria desperta uma natureza bestial interior. Em fúria, o bárbaro desenvolve armas naturais como mordida, garras ou cauda; mais tarde ganha adaptações animais para escalar, nadar e saltar, e pode contagiar inimigos com uma fúria enlouquecedora. A origem da fera pode ser uma maldição, uma ancestralidade ou um espírito primitivo.",
  "dnd.s.barbarian.berserker": "O Caminho do Berserker é um caminho de bárbaro para quem se entrega à violência pura. Seu traço marcante, o Frenesi, permite desferir golpes extras durante a fúria; mais tarde ele resiste ao medo e ao encantamento enquanto está em fúria e pode aterrorizar inimigos com o olhar. É a expressão mais direta da fúria.",
  "dnd.s.barbarian.stormherald": "O Caminho do Arauto da Tempestade é um caminho de bárbaro cuja fúria assume a forma de uma tempestade primitiva. Em fúria, o bárbaro projeta uma aura moldada pelo ambiente escolhido: o calor do deserto, os relâmpagos do mar ou o frio revigorante da tundra, que concede pontos de vida temporários. A tempestade também concede resistências e, mais tarde, golpeia inimigos próximos.",
  "dnd.s.barbarian.wildheart": "O Caminho do Coração Selvagem é um caminho de bárbaro, a versão de 2024 do Guerreiro Totêmico, cuja fúria está ligada a espíritos animais. O bárbaro recorre a feras como o urso, a águia e o lobo para obter resistência, mobilidade ou trabalho em equipe, e pode se comunicar com animais. Seus poderes nascem do parentesco com o mundo natural.",
  "dnd.s.bard.creation": "O Colégio da Criação é um colégio de bardos inspirado na Canção da Criação, a melodia primordial que, segundo dizem, moldou o cosmos. Esses bardos fortalecem aliados com Notas de Potencial e conseguem fazer surgir objetos não mágicos com o canto. Em níveis altos, dão vida a um objeto como um companheiro animado e dançante.",
  "dnd.s.bard.dance": "O Colégio da Dança é um colégio de bardos, apresentado no Livro do Jogador de 2024, cujos membros expressam a magia pelo movimento. Seu Gingado Deslumbrante transforma movimentos graciosos em defesa e golpes desarmados, e eles ajudam aliados a se reposicionar e agir rapidamente em combate. Mais tarde, conduzem os companheiros para longe do perigo com esquivas ágeis.",
  "dnd.s.bard.eloquence": "O Colégio da Eloquência é um colégio de bardos dedicado ao discurso persuasivo e à retórica. Seus bardos raramente falham ao persuadir ou enganar, minam a determinação do inimigo com Palavras Perturbadoras e inspiram aliados tão bem que seu incentivo quase nunca é desperdiçado. Em níveis altos, qualquer criatura entende o que dizem.",
  "dnd.s.bard.glamour": "O Colégio do Glamour é um colégio de bardos enraizado na magia sedutora da Agrestia das Fadas. Esses bardos envolvem aliados num Manto de Inspiração, cativam plateias com apresentações fascinantes e podem assumir uma majestade sobrenatural que exige obediência. Sua arte empresta a graça e o encanto das fadas.",
  "dnd.s.cleric.life": "O Domínio da Vida é um domínio de clérigo voltado à energia positiva que sustenta todos os seres vivos. Seus clérigos são os maiores curandeiros: suas magias curam mais e, com Preservar a Vida, restauram muitos aliados de uma vez. Costumam servir a deuses da cura, da colheita e da vitalidade.",
  "dnd.s.cleric.tempest": "O Domínio da Tempestade é um domínio de clérigo que pertence aos deuses das tempestades, do mar e do céu. Seus clérigos empunham o trovão e o relâmpago, revidam contra atacantes com o poder da tempestade e canalizam a divindade para causar o dano máximo de relâmpago ou trovão. Muitas vezes usam armadura pesada e lutam na linha de frente.",
  "dnd.s.cleric.trickery": "O Domínio da Trapaça é um domínio de clérigo a serviço de deuses da travessura, dos ladrões e do engano. Seus clérigos abençoam aliados com furtividade, criam duplicatas ilusórias de si mesmos com Invocar Duplicidade e preferem magias de ilusão e distração. Agem como agentes astutos que minam a tirania e o orgulho.",
  "dnd.s.druid.dreams": "O Círculo dos Sonhos é um círculo de druidas ligado à Agrestia das Fadas e ao reino dos sonhos. Seus druidas curam aliados com o Bálsamo da Corte de Verão, protegem o acampamento com magia e percorrem caminhos ocultos que permitem teletransportes curtos. Eles guardam os mistérios gentis das fadas.",
  "dnd.s.druid.land": "O Círculo da Terra é um círculo de druidas místicos e sábios que protegem conhecimentos antigos. Cada druida tira poder de um tipo de terreno escolhido, ganhando magias ligadas a ele, e pode recuperar magia gasta enquanto descansa. As regras de 2014 oferecem terrenos como ártico, deserto, floresta e montanha, enquanto as de 2024 os simplificam para árido, polar, temperado e tropical.",
  "dnd.s.druid.moon": "O Círculo da Lua é um círculo de guardiões ferozes que confiam na Forma Selvagem em combate. Eles se transformam rapidamente em feras mais fortes que as de outros druidas, se sustentam enquanto transformados e, com o tempo, assumem formas elementais. Vigiam os lugares selvagens sob a lua mutável.",
  "dnd.s.druid.sea": "O Círculo do Mar é um círculo de druidas, apresentado no Livro do Jogador de 2024, que canaliza as marés e tempestades do oceano. Gastando um uso de Forma Selvagem, esses druidas se cercam da Ira do Mar, uma aura de borrifos marinhos que causa dano de frio e empurra inimigos. Mais tarde, nadam livremente, voam em ventos de tempestade e resistem a frio, relâmpago e trovão.",
  "dnd.s.fighter.battlemaster": "O Mestre de Batalha é um arquétipo de guerreiro para estrategistas que tratam o combate como uma disciplina acadêmica. Eles gastam dados de superioridade em manobras como desarmar, derrubar ou reanimar aliados, e sabem avaliar os pontos fortes dos oponentes. Sua habilidade vem de técnica longamente aprimorada, não de força bruta.",
  "dnd.s.fighter.champion": "O Campeão é um arquétipo de guerreiro focado na excelência física pura. Campeões conseguem acertos críticos com mais frequência, ganham atletismo aprimorado e, com o tempo, recuperam pontos de vida a cada turno quando estão gravemente feridos. É o caminho mais simples e direto do guerreiro.",
  "dnd.s.fighter.runeknight": "O Cavaleiro Rúnico é um arquétipo de guerreiro que domina a magia rúnica dos gigantes. Ele inscreve runas mágicas em seu equipamento para obter vários efeitos e pode crescer até o tamanho Grande com o Poder do Gigante, causando dano extra. À medida que se fortalece, fica ainda maior e usa suas runas com mais frequência.",
  "dnd.s.monk.astral": "O Caminho do Eu Astral é uma tradição monástica em que o ki assume a forma do verdadeiro eu do monge, projetado a partir do Plano Astral. Esses monges invocam braços astrais espectrais para golpear de mais longe e, mais tarde, um semblante e um corpo astral completo que aguçam seus sentidos e sua defesa. Sua prática é uma jornada de autodescoberta.",
  "dnd.s.monk.mercy": "O Caminho da Misericórdia é uma tradição monástica (chamada Guerreiro da Misericórdia nas regras de 2024) cujos monges manipulam a força vital para curar ou ferir. Muitas vezes usando uma máscara característica, eles fecham feridas e curam males com um toque, ou causam dano necrótico extra aos inimigos. Caminham na linha entre a vida e a morte.",
  "dnd.s.monk.openhand": "O Caminho da Mão Aberta é uma tradição monástica para mestres do combate desarmado (chamada Guerreiro da Mão Aberta nas regras de 2024). Suas rajadas de golpes podem derrubar inimigos, empurrá-los ou impedi-los de reagir, e com a Integridade Corporal eles podem curar a si mesmos. No ápice do treinamento, aprendem a mortal Palma Vibrante.",
  "dnd.s.paladin.conquest": "O Juramento de Conquista é um juramento de paladino para quem busca glória por meio da vitória e da ordem absoluta. Seus paladinos espalham medo no campo de batalha, e sua aura pune inimigos amedrontados, na crença de que a força deve esmagar o caos. Seus preceitos exigem extinguir toda esperança nos inimigos.",
  "dnd.s.paladin.devotion": "O Juramento de Devoção é um juramento de paladino que encarna os ideais clássicos do cavaleiro reluzente: honestidade, coragem, compaixão e dever. Seus paladinos fazem a arma brilhar com poder sagrado por meio da Arma Sagrada, e sua aura protege os aliados contra encantamentos. Eles se esforçam para ser faróis de justiça e virtude.",
  "dnd.s.paladin.glory": "O Juramento de Glória é um juramento de paladino para heróis que acreditam que eles e seus companheiros estão destinados a grandes feitos. Seus paladinos se destacam em façanhas atléticas, inspiram aliados com seus golpes de destruição e concedem velocidade extra com sua aura. Treinam sem descanso para estar à altura dos heróis lendários que admiram.",
  "dnd.s.paladin.vengeance": "O Juramento de Vingança é um juramento de paladino dedicado a punir quem comete males graves. Seus paladinos marcam um inimigo escolhido com o Voto de Inimizade para levar vantagem contra ele e perseguem sua presa implacavelmente. Estão dispostos a abrir mão da própria pureza se for preciso para destruir o mal.",
  "dnd.s.ranger.beastmaster": "O Mestre das Feras é um arquétipo de patrulheiro ligado a um companheiro animal. Patrulheiro e fera lutam como uma equipe; nas regras mais recentes, o companheiro é uma fera primitiva da terra, do mar ou do céu que o patrulheiro convoca. A confiança mútua se aprofunda conforme avançam.",
  "dnd.s.ranger.gloomstalker": "O Perseguidor Sombrio é um arquétipo de patrulheiro que se sente em casa nos lugares mais escuros, como o Subterrâneo. Ele ataca primeiro e com mais força no início do combate graças ao Emboscador Terrível e se torna quase invisível para criaturas que dependem da visão no escuro. Sua mente também é endurecida contra o medo e a intrusão.",
  "dnd.s.ranger.hunter": "O Caçador é um arquétipo de patrulheiro que se coloca entre a civilização e os horrores das terras selvagens. Caçadores escolhem técnicas especializadas contra suas presas, como abrir caminho entre hordas, derrubar gigantes ou se esquivar de ataques. São defensores versáteis que se adaptam a qualquer ameaça.",
  "dnd.s.rogue.arcanetrickster": "O Trapaceiro Arcano é um arquétipo de ladino que soma magia de ilusão e encantamento à furtividade e agilidade. Ele usa uma Mão Mágica invisível para bater carteiras e abrir fechaduras à distância e, mais tarde, emprega magias para confundir e emboscar seus alvos. Sua magia serve à arte do engano.",
  "dnd.s.rogue.inquisitive": "O Inquisitivo é um arquétipo de ladino para detetives que desvendam segredos e mentiras. Seus sentidos aguçados percebem falsidades e detalhes ocultos, e ele consegue estudar um inimigo o bastante para encontrar uma brecha para o Ataque Furtivo. Destaca-se em investigação, interrogatório e resolução de mistérios.",
  "dnd.s.rogue.swashbuckler": "O Espadachim é um arquétipo de ladino de duelistas ousados que confiam em velocidade, elegância e charme. Ele escapa dos inimigos depois de atacar, pode usar o Ataque Furtivo num duelo um contra um e usa sua Panache para cativar ou provocar os outros. É o herói arrojado das histórias de aventura.",
  "dnd.s.sorcerer.aberrant": "A Feitiçaria Aberrante é uma origem de feiticeiro cujo poder vem de uma influência alienígena, como o Reino Distante, devoradores de mentes ou um estranho evento psiônico. Esses feiticeiros falam por telepatia, aprendem magias psiônicas que podem conjurar com discrição e, com o tempo, transformam o próprio corpo de maneiras perturbadoras. Ela surgiu como Mente Aberrante no Caldeirão de Tasha para Tudo.",
  "dnd.s.sorcerer.draconic": "A Feitiçaria Dracônica é uma origem de feiticeiro cuja magia vem do sangue dos dragões. Esses feiticeiros têm pele naturalmente resistente e escamosa, fortalecem magias do elemento de seu ancestral dracônico e, com o tempo, ganham asas de dragão e irradiam uma aura de assombro. Sua personalidade costuma refletir o orgulho dos dragões.",
  "dnd.s.sorcerer.storm": "A Feitiçaria da Tempestade é uma origem de feiticeiro alimentada pelo ar elemental. Esses feiticeiros são envoltos em vento e relâmpagos, podem voar uma curta distância ao conjurar magias e, mais tarde, resistem a relâmpago e trovão enquanto dobram o clima à sua vontade. Seu poder costuma ser atribuído a uma grande tempestade ou ao Plano Elemental do Ar.",
  "dnd.s.sorcerer.wildmagic": "A Feitiçaria de Magia Selvagem é uma origem de feiticeiro cujo poder vem das forças caóticas da magia bruta. Conjurar magias pode desencadear um Surto de Magia Selvagem imprevisível, útil ou bizarro, e esses feiticeiros podem dobrar a sorte com as Marés do Caos. Sua magia é empolgante, mas nunca está totalmente sob controle.",
  "dnd.s.warlock.archfey": "O Patrono Arquifada é um patrono de bruxo que liga o bruxo a um poderoso senhor ou senhora das fadas. Esses bruxos encantam ou amedrontam os outros e escapam do perigo com passos nebulosos de teletransporte. Seus patronos são seres caprichosos da Agrestia das Fadas, com sensibilidades e vontades estranhas aos mortais.",
  "dnd.s.warlock.celestial": "O Patrono Celestial é um patrono de bruxo que une o bruxo a um ser dos Planos Superiores, como um empíreo ou um unicórnio. Esses bruxos curam com a Luz Curativa, causam dano radiante e de fogo e, mais tarde, podem se reerguer à beira da morte. Seu poder lembra o de um clérigo, mas nasce de um vínculo pessoal.",
  "dnd.s.warlock.fiend": "O Patrono Ínfero é um patrono de bruxo que oferece um pacto com um ser dos Planos Inferiores, como um lorde demônio ou um arquidiabo. Esses bruxos ganham pontos de vida temporários ao derrubar inimigos, recorrem a uma sorte sombria e se tornam resistentes a danos. Esses acordos são perigosos e nunca saem de graça de verdade.",
  "dnd.s.warlock.greatoldone": "O Patrono Grande Antigo é um patrono de bruxo cujo poder vem de uma entidade incompreensível, muito além dos planos conhecidos. Esses bruxos ganham telepatia, protegem os próprios pensamentos e podem dobrar a mente de outros. Seu patrono pode nem saber que eles existem, concedendo conhecimento proibido em vez de orientação.",
  "dnd.s.wizard.enchantment": "A Escola de Encantamento é uma tradição de mago especializada em magias que influenciam mentes e comportamentos. Esses magos podem hipnotizar inimigos com o olhar, desviar ataques e, mais tarde, alterar as memórias de quem encantam. Eles acreditam que persuasão e controle podem resolver conflitos sem derramamento de sangue.",
  "dnd.s.wizard.illusion": "O Ilusionista é um mago especializado em magia enganosa que ilude os sentidos. Suas ilusões são especialmente convincentes, podem ser alteradas depois de conjuradas e até se tornar parcialmente reais. Ele também se protege com duplicatas ilusórias que confundem os atacantes.",
  "dnd.s.wizard.transmutation": "A Escola de Transmutação é uma tradição de mago especializada em magias que alteram matéria e energia. Esses magos podem transformar temporariamente um material em outro, criar uma pedra de transmutador que concede vários benefícios e mudar a própria forma. No auge do poder, realizam transformações milagrosas.",
  "dnd.al.CE": "Personagens Caótico e Mau agem com violência arbitrária, movidos por ganância, ódio ou sede de sangue. Rejeitam a ordem e geralmente só se mantêm unidos por medo de um líder mais forte. Os demônios do Abismo e os dragões vermelhos são os exemplos clássicos do Livro do Jogador.",
  "dnd.al.CG": "Personagens Caótico e Bom seguem a própria consciência, sem se importar muito com o que os outros esperam. Valorizam a liberdade e a bondade e desconfiam de regras que atrapalham fazer o bem. Dragões de cobre, muitos elfos e unicórnios são os exemplos do Livro do Jogador.",
  "dnd.al.CN": "Personagens Caótico e Neutro seguem seus caprichos e valorizam a liberdade pessoal acima de tudo. Não são movidos por maldade nem por altruísmo, mas por independência. Segundo o Livro do Jogador, muitos bárbaros e ladinos, e alguns bardos, tendem a essa tendência.",
  "dnd.al.LE": "Personagens Leal e Mau tomam o que querem de forma metódica, dentro dos limites de um código, de uma tradição ou de uma hierarquia. Honram contratos e lealdades enquanto isso os beneficia. Os diabos dos Nove Infernos são o exemplo arquetípico, ao lado de tiranos e oficiais ardilosos.",
  "dnd.al.LG": "Personagens Leal e Bom tentam fazer a coisa certa do jeito que a sociedade espera: cumprem a palavra, respeitam a autoridade legítima e protegem os inocentes. Paladinos e cavaleiros justiceiros são a imagem clássica. Sua fraqueza típica é a rigidez, confundir as regras com o próprio bem.",
  "dnd.al.LN": "Personagens Leal e Neutro agem segundo a lei, a tradição ou um código pessoal, e não por bondade ou crueldade. O valor está na própria ordem. Juízes, soldados disciplinados e muitos monges se encaixam nessa tendência.",
  "dnd.al.NE": "Personagens Neutro e Mau fazem tudo o que puderem sem sofrer consequências, só por interesse próprio, sem lealdade à lei nem amor pelo caos. É o egoísmo em sua forma mais pura. Os yugoloths, abissais mercenários, são as criaturas neutras e más por excelência.",
  "dnd.al.NG": "Personagens Neutro e Bom fazem todo o bem que podem, sem forte inclinação a favor ou contra as regras. Ajudam onde a ajuda é necessária, colaborando com a autoridade ou contornando-a conforme a situação. No Livro do Jogador, muitos celestiais e a maioria dos gnomos são neutros e bons.",
  "dnd.al.NN": "Personagens de tendência Neutro ficam longe dos extremos morais e éticos, seja evitando escolhas difíceis, seja buscando o equilíbrio de propósito. Alguns druidas veem a neutralidade como harmonia com a ordem natural. O Livro do Jogador considera neutros a maioria dos druidas e muitos humanos.",
  "dnd.r.changeling": "Os Metamorfos são mudadores de forma capazes de alterar a aparência e a voz à vontade, assumindo um novo rosto sempre que quiserem. Vêm do cenário de Eberron e depois apareceram em Mordenkainen Presents: Monsters of the Multiverse. Sua forma verdadeira é pálida, com olhos sem cor, e muitos Metamorfos mantêm várias personas para situações diferentes.",
  "dnd.r.dragonborn": "Os Draconatos são humanoides orgulhosos de ascendência dracônica, com corpo escamoso e cabeça de dragão. Cada um é ligado a um tipo de dragão, que define o dano de sua arma de sopro e sua resistência: ácido, frio, fogo, elétrico ou veneno. Clã e honra são muito importantes para eles, e nos Reinos Esquecidos estão ligados à nação de Tymanther.",
  "dnd.r.drow": "Os Drow são os elfos negros do Subterrâneo, o vasto mundo sob a superfície. Tradicionalmente vivem em cidades matriarcais como Menzoberranzan, governadas por sacerdotisas de Lolth, a deusa aranha. Têm visão no escuro superior e magia inata como fogo das fadas e escuridão. Drizzt Do'Urden, que deixou seu povo pela superfície, é o Drow mais famoso.",
  "dnd.r.dwarf": "Os Anões são um povo robusto e longevo, famoso como mineiros, ferreiros e construtores de salões escavados nas montanhas. São resistentes, aguentam veneno e enxergam no escuro. Clã, ancestrais e antigos rancores pesam muito em sua cultura, e Moradin, o Forjador de Almas, lidera o panteão anão.",
  "dnd.r.elf": "Os Elfos são um povo gracioso e longevo, profundamente ligado à magia e à Agrestia das Fadas. Em vez de dormir, descansam algumas horas em um transe meditativo. Sua ascendência feérica os ajuda a resistir a encantamentos. Existem muitas linhagens élficas, como os altos elfos, os elfos da floresta e os drow.",
  "dnd.r.goliath": "Os Golias são um povo de grande estatura aparentado aos gigantes, que tradicionalmente vive nas altas montanhas. No Livro do Jogador de 2024, cada Golias tem uma ascendência gigante que concede uma dádiva sobrenatural, como o poder do fogo, do gelo ou da tempestade, e pode crescer brevemente até o tamanho Grande. Sua cultura valoriza a competição justa e a conquista pessoal.",
  "dnd.r.halfling": "Os Pequeninos são um povo pequeno e alegre que valoriza o lar, a boa comida e comunidades unidas. São famosos pela sorte, que lhes permite rolar de novo um 1 natural. São corajosos para o seu tamanho e ágeis o bastante para passar por criaturas maiores. Muitos vivem em vilarejos tranquilos próprios ou entre humanos.",
  "dnd.r.halforc": "Os Meio-Orcs combinam herança humana e orc e eram uma raça jogável no Livro do Jogador de 2014. São conhecidos pela força e resistência: ao sofrer um golpe fatal, podem cerrar os dentes e continuar de pé com 1 ponto de vida. Seus ataques selvagens causam dano extra em acertos críticos. Nas regras de 2024, a espécie orc ocupa o seu lugar.",
  "dnd.r.human": "Os Humanos são o povo mais difundido e variado na maioria dos mundos de D&D. Sua vida é curta comparada à dos elfos ou anões, o que os leva à ambição e a realizações rápidas. Nas regras de 2024 são conhecidos pela engenhosidade e versatilidade, ganhando Inspiração Heroica após cada descanso longo e uma perícia extra.",
  "dnd.r.kenku": "Os Kenku são um povo-pássaro parecido com corvos que não consegue voar. São famosos pela imitação, reproduzindo sons e vozes que já ouviram. Também têm uma memória afiada para detalhes. Lendas antigas contam que perderam as asas e a própria voz como castigo por uma traição ancestral.",
  "dnd.r.tabaxi": "Os Tabaxi são humanoides felinos que, nos Reinos Esquecidos, vêm da distante terra de Maztica. São movidos pela curiosidade e adoram colecionar histórias, objetos e experiências. Suas garras ajudam a escalar, sua agilidade felina permite arrancadas curtas e eles enxergam bem na penumbra.",
  "dnd.r.tiefling": "Os Tiferinos carregam no sangue um legado ínfero, muitas vezes visível em chifres, cauda e cores incomuns de pele ou olhos. Nos Reinos Esquecidos, muitos atribuem essa herança a Asmodeus, senhor dos Nove Infernos. As regras de 2024 oferecem legados abissal, ctônico e infernal, cada um com sua resistência e magias inatas. Costumam enfrentar desconfiança, mas sua herança não define seu caráter.",
  "dnd.r.yuanti": "Os Yuan-ti são um povo serpentino descendente de humanos transformados por rituais antigos dedicados a deuses-serpente. Seus impérios já dominaram as selvas, e muitos ainda sonham em restaurá-los. Como personagens jogadores em Monsters of the Multiverse, resistem a magia e veneno e têm magia inata capaz de encantar serpentes.",
  "wi.g.aard": "Aard é um sinal que libera uma explosão telecinética, empurrando, desequilibrando ou atordoando os inimigos. Os bruxos também o usam para derrubar paredes, portas e outros obstáculos. Nos jogos, é um dos cinco sinais básicos, e suas formas aprimoradas podem atingir inimigos ao redor do bruxo.",
  "wi.g.axii": "Axii é um sinal que afeta a mente, acalmando, confundindo ou enfeitiçando o alvo. Nos livros, Geralt o usa para acalmar animais ou dobrar brevemente a vontade de alguém. Nos jogos, pode fazer um inimigo parar de lutar ou até se voltar contra os aliados, além de abrir opções extras de diálogo.",
  "wi.g.igni": "Igni é um sinal que libera uma rajada de fogo, queimando inimigos e incendiando objetos. É especialmente eficaz contra criaturas vulneráveis às chamas. Em The Witcher 3, sua forma avançada produz um jato contínuo de fogo.",
  "wi.g.quen": "Quen é um sinal protetor que envolve o bruxo em um escudo mágico que absorve dano. É a defesa padrão do bruxo em lutas perigosas. Em The Witcher 3, uma forma alternativa cria um escudo ativo que recupera a vida do bruxo enquanto absorve golpes.",
  "wi.g.yrden": "Yrden é um sinal que desenha um glifo mágico no chão, deixando lentos os inimigos que entram nele. É essencial contra espectros e outros seres incorpóreos, que se tornam tangíveis dentro do círculo. Em The Witcher 3, uma forma alternativa o transforma em uma armadilha mágica que atinge inimigos próximos.",
  "wi.s.bear": "A Escola do Urso é conhecida pela armadura pesada e por bruxos poderosos e resistentes, capazes de aguentar muita pancada. Sua fortaleza se chama Haern Caduch. Os bruxos do Urso tinham fama de viver isolados e de ter um temperamento sombrio e solitário.",
  "wi.s.cat": "A Escola do Gato formava lutadores ágeis e rápidos, de armadura leve, que preferiam velocidade à defesa. Seus bruxos têm má reputação, e muitos trabalharam como assassinos ou mercenários. Algumas fontes descrevem a escola sem uma fortaleza fixa, viajando de lugar em lugar. Gaetan, de The Witcher 3, é um de seus membros.",
  "wi.s.griffin": "A Escola do Grifo dá mais peso aos sinais do que as outras escolas, e seus bruxos são conhecidos por um código de conduta cavalheiresco. Sua fortaleza, Kaer Seren, ficava no litoral. Ali treinou Coën, amigo de Geralt nos livros. Seu equipamento em The Witcher 3 é uma armadura média, adequada a um estilo baseado em sinais.",
  "wi.s.manticore": "A Escola da Mantícora é uma das escolas de bruxos menos conhecidas, mencionada principalmente em materiais complementares, como o RPG de mesa. Há poucos detalhes firmes no cânone sobre sua fortaleza, seus membros e seus métodos, por isso as descrições variam entre as fontes. Como as outras escolas, leva o nome de uma fera temível.",
  "wi.s.viper": "A Escola da Víbora está associada às terras do sul e ao Império de Nilfgaard. Seu membro mais famoso é Letho de Gulet, o Regicida de The Witcher 2. Sua fortaleza se chama Gorthur Gvaed, e seus bruxos são ligados a venenos e a um equipamento leve e ágil.",
  "wi.s.wolf": "A Escola do Lobo treinava seus bruxos em Kaer Morhen, uma fortaleza nas Montanhas Azuis de Kaedwen. É a escola de Geralt de Rívia, junto com Vesemir, Eskel e Lambert. A fortaleza foi atacada há muito tempo, e depois disso restou apenas um punhado de bruxos. Os bruxos do Lobo equilibram esgrima, sinais e alquimia.",
  "av.e.water": "Água é o elemento da mudança. Os dobradores de água, que vivem principalmente nas Tribos da Água do Norte e do Sul, aprenderam sua arte com a Lua e com o vaivém do oceano. Seu poder cresce na lua cheia e enfraquece na lua nova. A dobra de água inclui técnicas avançadas como a cura, a dobra de plantas e a dobra de sangue.",
  "av.e.earth": "Terra é o elemento da substância. Os dobradores de terra, mais comuns no Reino da Terra, aprenderam com os texugos-toupeira, os primeiros dobradores de terra. Seu estilo se baseia em permanecer firme e esperar o momento certo para atacar. Suas sub-habilidades incluem a dobra de metal, de areia e de lava.",
  "av.e.fire": "Fogo é o elemento do poder. Os dobradores de fogo, em sua maioria da Nação do Fogo, aprenderam originalmente com os dragões, e sua força vem da respiração e da energia interior. A dobra de fogo fica mais forte com o sol e desaparece durante um eclipse solar. Suas formas avançadas incluem a geração de raios e a dobra de combustão.",
  "av.e.air": "Ar é o elemento da liberdade. Os dobradores de ar aprenderam com os bisões voadores e viviam como Nômades do Ar em quatro templos. Depois do ataque da Nação do Fogo aos Nômades, Aang foi o último dobrador de ar, até que novos dobradores de ar surgiram após a Convergência Harmônica. A dobra de ar é evasiva e defensiva, baseada em movimentos circulares.",
  "av.t.vines": "Plantas é uma técnica da dobra de água que controla a água dentro dos vegetais, permitindo mover cipós, raízes e outras plantas. Foi desenvolvida pela Tribo do Pântano Nebuloso. Ela mostra que a dobra de água pode trabalhar com seres vivos, não só com água livre.",
  "av.t.sand": "Areia é uma sub-habilidade da dobra de terra para controlar areia solta. Foi desenvolvida pelos dobradores de areia do deserto de Si Wong, que a usam para impulsionar veleiros de areia pelas dunas e levantar tempestades de areia. Exige um controle mais fino do que a dobra de terra comum.",
  "av.t.healing": "Cura é uma habilidade da dobra de água em que o dobrador guia a água pelos caminhos de energia do corpo para fechar ferimentos e aliviar a dor. Katara é uma curandeira talentosa. A água do Oásis Espiritual, no Polo Norte, tem um poder de cura especial, como quando Katara a usou para salvar Aang.",
  "av.t.metal": "Metal é uma técnica da dobra de terra inventada por Toph Beifong, que sentiu vestígios de terra dentro do metal e aprendeu a dobrá-lo. Metais muito puros, como a platina, não podem ser dobrados. Na época de A Lenda de Korra, a técnica já era comum, usada pela polícia da Cidade República e pelo clã do metal de Zaofu.",
  "av.t.lightning": "Raio é uma habilidade avançada da dobra de fogo, às vezes chamada de fogo de sangue frio, em que o dobrador separa a energia positiva da negativa e deixa que voltem a se chocar. Azula, Ozai e Iroh a dominavam. Iroh também criou uma técnica para redirecionar raios pelos caminhos de energia do corpo.",
  "av.t.blood": "Sangue é uma técnica da dobra de água que controla a água dentro de um corpo vivo, assumindo os movimentos do alvo. Hama a desenvolveu como prisioneira da Nação do Fogo e a usava na lua cheia. Mais tarde foi proibida; em A Lenda de Korra, Yakone e seus filhos conseguiam usá-la mesmo sem lua cheia.",
  "av.t.lava": "Lava é uma sub-habilidade rara da dobra de terra que transforma rocha em lava derretida e de volta em rocha. Em A Lenda de Korra, Ghazan, do Lótus Vermelho, e depois Bolin a dominaram. Alguns Avatares, como Roku, também conseguiam usá-la.",
  "av.t.combustion": "Combustão é uma sub-habilidade rara da dobra de fogo em que o dobrador cria explosões concentrando energia com a mente. Seus usuários costumam ter uma tatuagem de terceiro olho na testa. Os dobradores de combustão mais conhecidos são o Homem Combustão e P'Li, do Lótus Vermelho.",
  "av.t.spirit": "A Dobra de energia é a forma mais antiga de dobra e existia antes de os quatro elementos serem dobrados. As tartarugas-leão a usavam para conceder às pessoas o poder dos elementos. Aang a usou para tirar a dobra de Ozai, e mais tarde ela fez parte de como Korra devolveu a dobra a outras pessoas.",
  "av.avatar": "O Avatar é o mestre dos quatro elementos e a ponte entre o mundo humano e o Mundo Espiritual. O ciclo começou com Wan, que se fundiu com Raava, o espírito da luz e da paz. Quando o Avatar morre, renasce na próxima nação do ciclo: Fogo, Ar, Água, Terra. No Estado Avatar, pode recorrer ao poder e ao conhecimento de suas vidas passadas.",
  "wod.aus.ahroun": "Os Ahroun são Garou nascidos sob a lua cheia, os guerreiros da Nação Garou. Sua Fúria queima mais forte que a de qualquer outro augúrio, e espera-se que fiquem na linha de frente contra a Wyrm e seus servos. Seus Dons favorecem a batalha, a resistência e o comando em combate. Muitos tombam lutando, e os que sobrevivem carregam a lembrança de cada companheiro de matilha perdido.",
  "wod.aus.galliard": "Nascidos sob a lua crescente gibosa, os Galliard são os dançarinos da lua entre os Garou: contadores de histórias, poetas e guardiões da história oral. Preservam as lendas da tribo, conduzem os grandes uivos nas assembleias e inflamam suas matilhas antes da batalha. Seus Dons tratam de comunicação, emoções e sonhos. Apaixonados por natureza, passam com a mesma facilidade à celebração e à fúria.",
  "wod.aus.philodox": "Os Philodox nascem sob a meia-lua, em equilíbrio entre a luz e a escuridão, e atuam como juízes e guardiões da lei entre os Garou. Conhecem a Litania de cor, resolvem disputas, supervisionam desafios e avaliam as reivindicações de Renome. Seus Dons os ajudam a discernir a verdade e a ler as intenções alheias. Respeitados e às vezes malvistos, precisam permanecer imparciais mesmo quando a própria matilha está envolvida.",
  "wod.aus.ragabash": "Nascidos sob a lua nova, os Ragabash são os trapaceiros e questionadores da Nação Garou. Seu dever sagrado é desafiar a tradição, expor a hipocrisia e impedir que os anciões se acomodem, muitas vezes por meio de pegadinhas. Seus Dons favorecem a furtividade, a astúcia e o engano. Têm menos Fúria que qualquer outro augúrio, mas são valorizados como batedores e como a voz que faz as perguntas incômodas.",
  "wod.aus.theurge": "Os Theurge nascem sob a lua crescente e são os videntes e intermediários dos espíritos entre os Garou. Comungam com os espíritos da Umbra, os prendem em fetiches e conduzem muitos dos ritos. Sua Gnose é alta e seus Dons tendem ao místico. Muitas vezes vistos como estranhos ou distantes, são ainda assim vitais para a sobrevivência de toda matilha.",
  "wod.breed.homid": "Os Hominídeos são Garou nascidos de pais humanos e criados entre humanos, geralmente sem conhecer sua herança até a Primeira Mudança. Hoje são a raça mais numerosa e entendem a sociedade e a tecnologia humanas muito melhor que seus parentes. Sua forma natural é a humana e começam com a menor Gnose. Alguns Garou, sobretudo as Garras Vermelhas, os olham com desconfiança.",
  "wod.breed.lupus": "Os Garou Lupinos nascem de lobos e vivem como parte de uma alcateia até a Primeira Mudança. Sua forma natural é a de lobo, e eles têm o vínculo mais próximo com Gaia e o mundo espiritual, o que se reflete em sua Gnose elevada. Conceitos humanos como dinheiro, escrita ou horário costumam confundi-los. À medida que os lobos selvagens desaparecem, essa raça também diminui.",
  "wod.breed.metis": "Esses Garou nascem da união entre dois lobisomens, uma união proibida pela Litania. Vêm ao mundo na forma Crinos, a forma de guerra, não podem ter descendência própria e cada um traz uma deformidade física que denuncia sua origem. Tratados por muito tempo como párias e motivo de vergonha, ainda assim crescem dentro da seita e muitas vezes conhecem a sociedade Garou e a Umbra mais a fundo que qualquer outro. Sua forma natural é Crinos.",
  "wod.gen": "A geração indica quantos Abraços separam um vampiro de Caim, o primeiro dos membros. Quanto mais baixa a geração, mais potente o sangue: ela permite Características mais altas, uma reserva de sangue maior e gastar mais sangue por turno. Neófitos recém-Abraçados costumam ser da décima segunda ou décima terceira geração, enquanto os Antediluvianos da Terceira Geração são quase míticos. A diablerie, devorar a alma de um vampiro de geração mais baixa, é a única forma de reduzir a própria.",
  "wod.gnosis": "A Gnose é a conexão espiritual de um Garou com Gaia e a Umbra. Ela alimenta muitos Dons, permite que um lobisomem atravesse para o mundo espiritual e é necessária para ativar fetiches e talens. Lupinos e Theurge costumam ter mais Gnose. Gnose e Fúria puxam em direções opostas, pois a ira dificulta o foco espiritual.",
  "wod.path.accord": "A Trilha do Acordo Honrado é uma Trilha de Iluminação do Sabá baseada na cavalaria, na lealdade e em honrar a palavra dada. Seus seguidores, os Cavaleiros, acreditam que a honra e o dever para com a seita, a matilha e os líderes são o que mantém a Besta sob controle. É popular entre os guerreiros e guardiões da seita. Quebrar um juramento ou trair um companheiro é o mais grave dos pecados.",
  "wod.path.blood": "A Trilha do Sangue é o código moral tradicional dos Assamitas, enraizado nos ensinamentos de seu fundador, Haqim. Seus seguidores consideram os demais membros amaldiçoados e acreditam que tomar seu sangue, sobretudo por meio da diablerie, os aproxima de Haqim. Ela exige disciplina, lealdade ao clã e o julgamento dos descendentes indignos de Caim.",
  "wod.path.caine": "Os seguidores da Trilha de Caim, chamados noddistas, estudam as lendas do primeiro vampiro tal como preservadas no Livro de Nod. Não veem o vampirismo como uma maldição da qual fugir, mas como uma condição a ser compreendida e dominada, e tomam Caim como modelo. São estudiosos, debatedores e buscadores de saber antigo, e consideram a diablerie e o uso deliberado da Besta ferramentas aceitáveis. A trilha é mais comum no Sabá.",
  "wod.path.cathari": "A Trilha dos Cátaros se inspira na heresia cátara medieval, que afirmava que o mundo material é obra do mal. Seus seguidores se veem como espíritos condenados cujo papel é encarnar a indulgência e a tentação, e buscam abertamente a paixão e o excesso em vez de contê-los. Ainda assim mantêm um código próprio, escolhendo com cuidado quem tentar e quem Abraçar.",
  "wod.path.feral": "A Trilha do Coração Selvagem ensina que os vampiros são predadores e que a Besta é uma parte natural deles, e não uma inimiga. Seus seguidores vivem segundo os instintos do caçador: matam quando têm fome, defendem seu território e evitam a crueldade desnecessária. É especialmente popular entre os Gangrel e outros membros próximos da natureza selvagem, e está associada ao Sabá.",
  "wod.path.humanity": "A Humanidade é a bússola moral à qual a maioria dos membros se agarra, uma medida de quanto de sua consciência mortal sobrevive ao Abraço. Ela segue a ética humana comum: não matar, não roubar, respeitar os outros. À medida que a Humanidade cai, o vampiro se torna mais frio, mais monstruoso e mais vulnerável à Besta. A maioria dos vampiros da Camarilla a segue, enquanto muitos no Sabá a abandonam por uma Trilha de Iluminação.",
  "wod.path.lilith": "Os seguidores da Trilha de Lilith, os bahari, veneram Lilith, a primeira esposa de Caim, que segundo suas lendas lhe ensinou os segredos da noite. Acreditam que a dor é a grande mestra e que o sofrimento traz crescimento e sabedoria. Seus ritos são místicos e secretos, e muitos membros os consideram hereges perigosos que contradizem o Livro de Nod.",
  "wod.path.metamorph": "A Trilha da Metamorfose pertence sobretudo aos Tzimisce, especialmente a seus anciões e estudiosos. Seus seguidores veem o vampirismo como um estágio de transformação a ser transcendido e usam a Disciplina Vicissitude para remodelar o corpo e estudar a natureza dos membros. Consideram as emoções uma distração irrelevante e buscam o conhecimento sem ceder aos outros nem a si mesmos.",
  "wod.path.night": "A Trilha da Noite, criada pelos Lasombra, sustenta que os vampiros são condenados por Deus e que seu papel é ser a escuridão que põe a humanidade à prova. Seus seguidores, os niilistas, espalham o medo entre os mortais para que apenas os verdadeiramente fiéis encontrem a salvação. Veem a si mesmos como instrumentos de um plano divino, e não como meros monstros. É seguida principalmente pelos Lasombra e por outros membros do Sabá.",
  "wod.path.paradox": "A Trilha do Paradoxo é o ethos tradicional do clã Ravnos e se baseia em conceitos indianos como samsara e svadharma. Seus seguidores acreditam que os vampiros caíram para fora do ciclo de renascimentos e que seu dever é atravessar a ilusão e restaurar o fluxo correto do cosmos, às vezes eliminando quem o obstrui. É pouco conhecida fora do clã.",
  "wod.path.power": "Os seguidores da Trilha do Poder e da Voz Interior, os unificadores, acreditam que a iluminação vem do domínio de si mesmo e do acúmulo de poder no mundo. São os políticos e estrategistas ambiciosos do Sabá, que valorizam resultados acima de sentimentos e usam o medo e a dor como ferramentas de controle. Misericórdia e fracasso são igualmente vistos como fraqueza. Muitos Lasombra e líderes do Sabá trilham este caminho.",
  "wod.path.scorched": "A Trilha do Coração Queimado, cujos seguidores são chamados de Implacáveis, ensina que as emoções são ferramentas da Besta e devem ser extintas pela razão fria. Ela está associada aos Verdadeiros Brujah e ao secreto Tal'Mahe'Ra. Seus adeptos rejeitam a moral como uma construção emocional, mas mantêm um código ético rígido, valorizam fatos acima de opiniões e se servem dos outros sempre que isso lhes traz proveito.",
  "wod.path.self": "A Trilha do Foco Interior é seguida pelos internalistas e está associada ao secreto Tal'Mahe'Ra. Inspirada em tradições espirituais asiáticas, ensina que não se pode mudar o mundo, apenas a si mesmo. Seus seguidores evitam se intrometer nos assuntos alheios, meditam com regularidade, vivem o presente e buscam o autodomínio para manter a Besta sob controle.",
  "wod.path.typhon": "A Trilha de Tifão é a fé ortodoxa dos Seguidores de Set. Seus adeptos, os teofidianos, acreditam que Set é um deus que um dia retornará e trabalham para libertar mortais e membros das correntes da convenção, da consciência e da fé por meio da tentação e da corrupção. Estudam os mistérios de Set e sustentam que ajudar em sua ressurreição é o dever supremo.",
  "wod.rage": "A Fúria é a ira dos guerreiros de Gaia, a raiva ardente que alimenta a força de um Garou em batalha. Ela permite que um lobisomem aja com velocidade sobrenatural, mude de forma num instante e continue lutando apesar dos ferimentos, mas também é perigosa: Fúria demais leva o Garou ao frenesi e perturba humanos e animais. Os Ahroun têm mais Fúria; os Ragabash, menos.",
  "wod.rank.adren": "Adren é o terceiro posto da sociedade Garou, alcançado por quem reuniu grande Renome. Os Adren são veteranos experientes, muitas vezes líderes de matilha ou oficiais da seita, e sua palavra tem peso nas assembleias. Espera-se que ensinem e orientem os de posto inferior.",
  "wod.rank.athro": "Athro é o quarto posto, alcançado por relativamente poucos Garou. Os Athro são heróis renomados cujos feitos são cantados nas canções de sua tribo, e muitas vezes ocupam cargos importantes na seita, como guardião do caern ou mestre do rito. Seu julgamento é amplamente respeitado.",
  "wod.rank.cliath": "Cliath é o primeiro posto verdadeiro da sociedade Garou, conquistado ao completar o Rito de Passagem. Um Cliath é aceito como membro pleno da tribo, mas ainda precisa provar seu valor, e a maioria dos personagens novos começa aqui. Eles ganham Renome cumprindo os deveres de seu augúrio e devem ouvir a orientação dos mais velhos.",
  "wod.rank.elder": "Ancião é o quinto posto, o mais alto normalmente alcançado na sociedade Garou. Os Anciões são figuras lendárias que lideram seitas e tribos e definem os rumos da Nação Garou; sua palavra tem um peso enorme. Apenas um punhado de Garou chega a esse posto.",
  "wod.rank.fostern": "Fostern é o segundo posto dos Garou, concedido àqueles cujos feitos renderam Renome suficiente para provar seu valor. Os Fostern já têm experiência e recebem tarefas mais importantes, como liderar uma matilha numa missão. São guerreiros e caçadores respeitados, mas ainda não estão entre os líderes da seita.",
  "wod.sect.cam": "A Camarilla é a maior seita dos membros, uma sociedade que afirma falar em nome de todos os vampiros. Em seu centro está a Máscara, a tradição de esconder a existência dos vampiros dos mortais, junto com as demais Tradições impostas por um Príncipe em cada cidade. Ventrue, Toreador, Tremere, Nosferatu, Malkavianos e Brujah formam sua espinha dorsal. Ela valoriza a ordem, a estabilidade e a autoridade dos anciões.",
  "wod.sect.sab": "O Sabá é uma seita de vampiros que rejeita a humildade da Máscara e o domínio dos Antediluvianos, considerando os membros superiores à humanidade. Seus integrantes se reúnem em bandos unidos pela Vaulderie, um ritual de sangue compartilhado que substitui os laços de sangue individuais pela lealdade à seita. Liderado pelos Lasombra e pelos Tzimisce, trava guerra contra a Camarilla e se prepara para o retorno dos Antediluvianos. Muitos de seus integrantes seguem Trilhas de Iluminação em vez da Humanidade.",
  "wod.vamp.assamite": "Os Assamitas são um clã de assassinos, guerreiros e estudiosos do Oriente Médio, descendentes de Haqim. Suas Disciplinas de clã são Rapidez, Ofuscação e Quietus, uma arte de sangue letal. Conhecidos há muito tempo por aceitar contratos sobre a vida de outros membros, muitas vezes pagos em vitae, já sofreram uma maldição dos Tremere que restringia sua diablerie. O clã se divide em castas de guerreiros, vizires e feiticeiros e se mantém à parte das grandes seitas.",
  "wod.vamp.brujah": "Os Brujah já foram reis-filósofos da antiga Cartago; hoje são conhecidos como rebeldes, idealistas e agitadores. Suas Disciplinas são Rapidez, Potência e Presença. Sua paixão é lendária e os torna propensos ao frenesi. A maioria pertence à Camarilla, embora sejam seus membros mais inquietos; outros se juntam aos anarquistas ou ao Sabá.",
  "wod.vamp.gangrel": "Os Gangrel são andarilhos que se sentem mais à vontade na natureza selvagem do que nas cidades. Suas Disciplinas são Animalismo, Fortitude e Metamorfose, que lhes permite criar garras, fundir-se à terra e assumir formas animais. Cada frenesi pode lhes deixar um traço animal duradouro. Independentes por natureza, afastaram-se da Camarilla, e muitos andam com os anarquistas ou com o Sabá.",
  "wod.vamp.giovanni": "Os Giovanni são um clã familiar de mercadores e necromantes venezianos. Suas Disciplinas são Dominação, Necromancia e Potência. Abraçam sobretudo membros de sua própria linhagem, detêm grande riqueza no mundo mortal e comandam os espíritos dos mortos. Ascenderam ao poder cometendo diablerie contra o próprio Antediluviano e hoje são independentes, presos por um antigo pacto com a Camarilla a não se intrometer em seus assuntos.",
  "wod.vamp.lasombra": "Os Lasombra são orgulhosos aristocratas da sombra e os líderes do Sabá. Suas Disciplinas são Dominação, Tenebrosidade e Potência; a Tenebrosidade lhes permite comandar a escuridão viva. Eles não têm reflexo nos espelhos. Muitos têm laços profundos com a Igreja, e valorizam a ambição, a excelência e a liderança.",
  "wod.vamp.malkavian": "Os Malkavianos são os loucos entre os membros: cada integrante do clã carrega um transtorno mental desde o momento do Abraço. Suas Disciplinas são Auspícios, Demência e Ofuscação, embora algumas linhagens pratiquem Dominação no lugar de Demência. Sua loucura lhes concede percepções estranhas e uma visão única da verdade, e muitos acreditam que compartilham um vínculo oculto conhecido como a Rede da Loucura Malkaviana. A maioria pertence à Camarilla, enquanto uma facção serve ao Sabá.",
  "wod.vamp.nosferatu": "Os Nosferatu ficam horrivelmente desfigurados pelo Abraço e precisam esconder o rosto dos mortais. Suas Disciplinas são Animalismo, Ofuscação e Potência. Fazem seus refúgios em esgotos e túneis sob as cidades e são os melhores negociantes de informação entre os membros. Apesar da aparência, costumam ser leais e práticos, e a maioria pertence à Camarilla.",
  "wod.vamp.setite": "Os Seguidores de Set são um clã de origem egípcia que adora seu Antediluviano, Set, como um deus. Suas Disciplinas são Ofuscação, Presença e Serpentis, que lhes concede traços de serpente. São conhecidos como tentadores e negociantes de vícios e segredos, convictos de que a corrupção liberta as almas de suas correntes. São independentes das seitas e amplamente vistos com desconfiança pelos demais membros.",
  "wod.vamp.toreador": "Os Toreador são artistas, estetas e amantes da beleza. Suas Disciplinas são Auspícios, Rapidez e Presença. Ocupam posição de destaque na Camarilla, onde moldam o Elísio e a vida cultural da cidade. Seu amor pela beleza também é sua fraqueza: algo verdadeiramente belo pode fasciná-los a ponto de esquecerem todo o resto.",
  "wod.vamp.tremere": "Os Tremere eram magos mortais que conquistaram a imortalidade por meio da magia de sangue. Suas Disciplinas são Auspícios, Dominação e Taumaturgia. São rigidamente organizados numa Pirâmide governada a partir de Viena, e seus membros estão ligados pelo sangue aos anciões do clã. São um pilar da Camarilla, valorizados por sua feitiçaria, mas vistos com desconfiança por sua ambição.",
  "wod.vamp.tzimisce": "Os Tzimisce são aristocratas do velho mundo, do Leste Europeu, estudiosos e mestres da carne. Suas Disciplinas são Animalismo, Auspícios e Vicissitude, que lhes permite moldar carne e osso. Precisam repousar na terra de sua pátria. Junto com os Lasombra lideram o Sabá, e muitos deles seguem a Trilha da Metamorfose.",
  "wod.vamp.ventrue": "Os Ventrue são o clã dos reis, os aristocratas e líderes da Camarilla. Suas Disciplinas são Dominação, Fortitude e Presença. Veem-se como guardiões da sociedade dos membros e muitas vezes detêm o título de Príncipe. Sua fraqueza é um paladar refinado: cada Ventrue só consegue se alimentar de um tipo específico de mortal.",
  "wod.wolf.fangs": "As Presas de Prata são as líderes tradicionais da Nação Garou, uma tribo de linhagem nobre que preza a pureza do sangue. Governam os Garou há eras, valorizando a honra, a pureza e a nobreza. No entanto, gerações de uniões entre parentes próximos deixaram muitos de seus membros com transtornos mentais, e sua autoridade é cada vez mais contestada. Seus Dons favorecem a liderança, a dignidade e a capacidade de inspirar os outros.",
  "wod.wolf.fenris": "As Crias de Fenris são guerreiros ferozes de origem nórdica e germânica que vivem para a batalha contra a Wyrm. Valorizam a força, a coragem e a glória, e consideram a fraqueza um vício. Seus Dons favorecem o combate, a resistência e a intimidação. Respeitados por sua bravura, também são criticados por sua dureza e intolerância.",
  "wod.wolf.fianna": "Os Fianna são Garou celtas, os bardos e contadores de histórias da Nação. São conhecidos por sua paixão, seu amor pela música e pela bebida e seu vínculo profundo com as fadas. Seus Dons favorecem a canção, a ilusão e o mundo feérico. Amigos leais e inimigos ferozes, mantêm vivas as histórias mais antigas dos Garou.",
  "wod.wolf.gaia": "Os Filhos de Gaia são os pacificadores da Nação Garou, trabalhando para unir as tribos e curar velhas feridas. Buscam a harmonia com a humanidade e acreditam que a diplomacia e a compaixão importam tanto quanto a batalha na guerra contra a Wyrm. Seus Dons favorecem a cura, a calma e a proteção. Outros às vezes os chamam de ingênuos, mas lutam com ferocidade quando necessário.",
  "wod.wolf.glass": "Os Andarilhos do Asfalto são Garou urbanos que abraçaram as cidades e a tecnologia. Circulam pelos negócios, pela informática e pela sociedade moderna, acreditando que os Garou precisam se adaptar ao mundo atual para sobreviver. Seus Dons favorecem a tecnologia, o ambiente urbano e a Umbra digital. Outras tribos muitas vezes suspeitam que estejam próximos demais da Weaver.",
  "wod.wolf.gnawers": "Os Roedores de Ossos são a tribo das ruas e vivem entre os sem-teto e os pobres das cidades. Desprezados pelas outras tribos, são sobreviventes engenhosos e humildes que protegem aqueles que a sociedade esqueceu. Seus Dons favorecem a sobrevivência, o aproveitamento de restos e o esconderijo. Poucos sabem mais do que eles sobre o que acontece numa cidade.",
  "wod.wolf.shadow": "Os Senhores das Sombras são Garou ambiciosos e calculistas com raízes no Leste Europeu, convictos de que a força e a astúcia devem decidir quem lidera. Há muito tempo disputam com as Presas de Prata a liderança da Nação. Seus Dons favorecem a intimidação, a manipulação e o poder das tempestades. Temidos e vistos com desconfiança, são ainda assim disciplinados e eficazes.",
  "wod.wolf.stargazers": "Os Observadores das Estrelas são Garou contemplativos com raízes na Ásia, que buscam o equilíbrio interior por meio da meditação e da filosofia. São conhecidos por suas artes marciais e sua percepção espiritual. Seus Dons favorecem a clareza, a percepção e o autocontrole. Em certos momentos se afastaram da Nação Garou e se aproximaram dos metamorfos do Oriente.",
  "wod.wolf.striders": "Os Peregrinos Silenciosos são andarilhos de origem egípcia, expulsos de sua terra há muito tempo e destinados a viajar sem descanso. São mensageiros, batedores e exploradores que percorrem tanto o mundo físico quanto a Umbra. Seus Dons favorecem a velocidade, as viagens e o contato com os mortos. Solitários por natureza, estão entre os Garou mais bem informados.",
  "wod.wolf.talons": "As Garras Vermelhas são uma tribo formada inteiramente por Garou Lupinos, que veem a humanidade como a maior ameaça a Gaia. São defensores ferozes da natureza selvagem e desprezam as cidades e a tecnologia humanas. Seus Dons favorecem a natureza, os sentidos e a destruição das obras humanas. Muitos sonham com o dia em que a população humana caia ao que a terra é capaz de suportar.",
  "wod.wolf.uktena": "Os Uktena são místicos e guardiões de segredos com raízes entre os povos indígenas das Américas, embora também aceitem membros de muitas outras culturas marginalizadas. Procuram e aprisionam os espíritos sombrios do mundo, mergulhando em saberes proibidos para que outros não possam usá-los mal. Seus Dons favorecem a magia, o oculto e o conhecimento secreto. As outras tribos valorizam sua sabedoria, mas temem os riscos que correm.",
  "wod.wolf.wendigo": "Os Wendigo são uma tribo feroz enraizada entre os povos indígenas da América do Norte. Guardam profundo ressentimento das tribos europeias pelas injustiças do passado e defendem suas terras e povos com lealdade feroz. Seus Dons favorecem o frio, o vento e os espíritos do inverno. Seu totem é o grande espírito Wendigo.",
  "wod.banality": "A Banalidade é a força gélida da descrença, da rotina e da razão fria que aos poucos mata o Sonhar. Todo changeling carrega um pouco dela, e quanto mais Banalidade tem, mais difícil fica lançar cantrips e lembrar da própria natureza feérica. Mortais e lugares banais podem desfazer a magia das fadas e lançar os changelings no esquecimento. Sem freio, ela termina na Desfeitura: a alma feérica se apaga e só resta o mortal.",
  "wod.court.seelie": "A Corte Seelie é a corte do verão, que por tradição governa a sociedade feérica de Beltane a Samhain. Seus membros defendem a honra, a cavalaria, a tradição e a nobreza que obriga, e entre seus ideais estão \"A morte antes da desonra\" e \"O amor tudo vence\". A maior parte da nobreza sidhe e do reino do Grão-Rei segue os costumes seelie. Todo changeling tem um lado seelie e um lado unseelie, e o lado seelie é o que cumpre promessas e protege os fracos.",
  "wod.court.unseelie": "A Corte Unseelie é a corte do inverno, que por tradição domina de Samhain a Beltane. Ela valoriza a paixão, a liberdade e a mudança acima do dever e do costume, com ideais como \"A mudança é boa\" e \"A paixão antes do dever\". As fadas unseelie não são simplesmente más, mas desconfiam da honra rígida e seguem os próprios desejos. Sua ala mais radical e oculta é a Corte das Sombras, que conspira para derrubar a ordem seelie.",
  "wod.demon.a.defilers": "Lammasu é o nome angelical original da Casa dos Profanadores, a Quinta Casa, muitas vezes chamados de Anjos das Profundezas. No princípio eles governavam os mares e as águas e moviam o coração humano rumo à beleza, à verdade e à inspiração. Seus Saberes são o Anseio, as Tempestades e a Transfiguração. Depois da Queda, seu dom de despertar o desejo se voltou para a tentação e a manipulação, o que lhes rendeu o nome mortal.",
  "wod.demon.a.devils": "Namaru é o nome angelical original da Casa dos Diabos, a Primeira Casa, os Arautos do Céu. Eles eram os porta-estandartes e as vozes de Deus, levando a vontade do Criador ao restante da Hoste e conduzindo os anjos. O próprio Lúcifer pertencia a esta casa, e muitos Namaru se tornaram generais da rebelião. Seus Saberes são os Celestiais, a Chama e o Esplendor.",
  "wod.demon.a.devourers": "Rabisu é o nome angelical original da Casa dos Devoradores, a Sexta Casa. Seus anjos criaram e cuidaram das plantas e dos animais do mundo, enchendo os seres vivos de vitalidade e instinto. Seus Saberes são a Fera, o Selvagem e a Carne. Na guerra contra o Céu eles aprenderam a transformar corpos vivos em armas, e a fome e a ferocidade daqueles dias lhes deram o nome mortal.",
  "wod.demon.a.fiends": "Neberu é o nome angelical original da Casa dos Malignos, a Quarta Casa, os anjos dos céus e das estrelas. Eles colocaram o cosmos em movimento e liam o grande padrão de seus movimentos, prevendo como os acontecimentos se desenrolariam. Seus Saberes são a Luz, os Padrões e os Portais. Depois da Queda tornaram-se mestres da profecia, da ilusão e do destino, temidos pelos mortais.",
  "wod.demon.a.malefactors": "Annunaki é o nome angelical original da Casa dos Malfeitores, a Terceira Casa, os Artífices da criação. Eles deram forma à pedra, ao solo e ao metal do mundo e fizeram as ferramentas que suas criaturas usariam. Seus Saberes são a Terra, os Caminhos e a Forja. Durante a guerra voltaram seu ofício à forja de armas e artefatos terríveis, o que lhes rendeu o nome mortal.",
  "wod.demon.a.scourges": "Asharu é o nome angelical original da Casa dos Flagelos, a Segunda Casa, os Anjos do Firmamento. Eles sopravam a vida nas criaturas recém-nascidas, governavam os ventos e o ar e zelavam pela humanidade como protetores e curandeiros. Seus Saberes são o Despertar, o Firmamento e os Ventos. Depois da Queda, esses mesmos poderes passaram a poder espalhar doença e sofrimento em vez de saúde.",
  "wod.demon.a.slayers": "Halaku é o nome angelical original da Casa dos Ceifadores, a Sétima Casa, os Anjos da Morte. Seu dever era encerrar o que já havia cumprido seu ciclo e devolvê-lo à criação para que pudesse recomeçar. Seus Saberes são a Morte, o Espírito e os Reinos. Quando a humanidade perdeu a imortalidade, os Halaku se tornaram portadores da morte verdadeira, e muitos moldaram o reino dos mortos inquietos.",
  "wod.demon.defilers": "Os Profanadores são a Quinta Casa dos Caídos, cujo nome angelical é Lammasu. Antes inspiravam a humanidade com a beleza dos mares e os impulsos do coração; depois da Queda tornaram-se tentadores que jogam com o anseio e o desejo. Seus Saberes são o Anseio, as Tempestades e a Transfiguração, que lhes permitem inflamar emoções, comandar a água e o clima e mudar de aparência. Muitas vezes são chamados de musas, às vezes para o bem e às vezes para o mal.",
  "wod.demon.devils": "Os Diabos são a Primeira Casa dos Caídos, os Namaru ou Arautos, a casa à qual Lúcifer pertencia. Eles eram os mensageiros de Deus e os líderes da Hoste, e na rebelião se tornaram seus comandantes. Orgulhosos, carismáticos e acostumados a liderar, os Diabos dominam os Saberes dos Celestiais, da Chama e do Esplendor. Atraem os outros apenas com sua presença e convicção.",
  "wod.demon.devourers": "Os Devoradores são a Sexta Casa dos Caídos, cujo nome angelical é Rabisu. Eles foram os pastores das plantas e dos animais e carregam a vitalidade primitiva e a fome dos seres vivos. Seus Saberes são a Fera, o Selvagem e a Carne, que lhes permitem comandar animais, despertar a natureza e remodelar corpos vivos. Os Devoradores são selvagens, apaixonados e guiados pelo instinto.",
  "wod.demon.fiends": "Os Malignos são a Quarta Casa dos Caídos, cujo nome angelical é Neberu. Eles foram os anjos que colocaram as estrelas em movimento e liam o padrão da criação. Seus Saberes são a Luz, os Padrões e os Portais, que concedem ilusões, vislumbres do destino e o poder de abrir passagens através do espaço. Os Malignos são estrategistas frios e analíticos que enxergam os fios por trás dos acontecimentos.",
  "wod.demon.malefactors": "Os Malfeitores são a Terceira Casa dos Caídos, cujo nome angelical é Annunaki. Eles foram os artífices que moldaram a terra e fizeram as ferramentas da criação. Seus Saberes são a Terra, os Caminhos e a Forja, que concedem poder sobre a pedra e o solo, sobre o deslocamento de um lugar a outro e sobre a criação de objetos encantados. Os Malfeitores são criadores práticos e pacientes que valorizam obras duradouras.",
  "wod.demon.scourges": "Os Flagelos são a Segunda Casa dos Caídos, cujo nome angelical é Asharu. Antes sopravam a vida nas criaturas e protegiam a humanidade como curandeiros e guardiões. Seus Saberes são o Despertar, o Firmamento e os Ventos, que lhes permitem curar ou ferir o corpo, perceber acontecimentos distantes e comandar o ar. Muitos Flagelos ainda sentem um vínculo protetor com os mortais, enquanto outros transformaram esse poder em praga.",
  "wod.demon.slayers": "Os Ceifadores são a Sétima Casa dos Caídos, cujo nome angelical é Halaku, os Anjos da Morte. Eles encerravam o que já tinha cumprido seu tempo e guiavam as almas adiante. Seus Saberes são a Morte, o Espírito e os Reinos, que concedem poder sobre a decomposição, sobre as almas dos mortos e sobre a passagem entre mundos. Os Ceifadores costumam ser solenes e calados e conhecem os finais como nenhuma outra casa.",
  "wod.fac.cryptic": "Os Crípticos são uma facção dos Caídos dedicada a compreender. Eles querem saber a verdade por trás do plano de Deus, as razões da guerra e da Queda e, talvez, o sentido da própria existência. Os Crípticos investigam, reúnem conhecimento e perseguem mistérios, acreditando que as respostas vão decidir o que os Caídos devem fazer. Formam uma facção pequena e pouco coesa.",
  "wod.fac.faustian": "Os Faustianos são uma facção dos Caídos que vê a humanidade como a chave do poder. Eles buscam prender os mortais por meio de pactos e colher sua Fé, acumulando força para retomar a guerra contra o Céu. São pragmáticos, ambiciosos e muitas vezes implacáveis em seus negócios com os humanos. Seu nome remete à lenda de Fausto e de seu pacto.",
  "wod.fac.luciferan": "Os Luciferianos são uma facção dos Caídos leal à memória de Lúcifer, a Estrela da Manhã que liderou a rebelião. Eles acreditam que ele ainda existe em algum lugar e aguardam seu retorno para que volte a liderá-los. Enquanto isso, tentam reconstruir a antiga hierarquia e a disciplina dos exércitos rebeldes. São a facção mais organizada e militante.",
  "wod.fac.ravener": "Os Devastadores são uma facção dos Caídos que perdeu a esperança de vitória ou de perdão. Convencidos de que a criação não tem mais salvação, buscam destruir o máximo possível dela como um último ato de desafio. São niilistas e violentos, e os outros demônios os encaram com medo e repulsa. Muitos se aproximaram dos Presos à Terra e de seus desígnios.",
  "wod.fac.reconciler": "Os Reconciliadores são uma facção dos Caídos que espera desfazer os danos da guerra. Eles querem devolver ao mundo o Paraíso que ele deveria ser e, talvez, conquistar o perdão de Deus. Muitos trabalham para curar tanto a terra quanto a humanidade, e alguns buscam uma reconciliação entre os Caídos e os mortais. Seu caminho é idealista, mas difícil, porque o Tormento do Abismo ainda os puxa para trás.",
  "wod.faith": "A Fé é a medida do poder de um demônio e seu vínculo com a centelha divina da criação. Desde que saíram do Abismo, os Caídos precisam extrair Fé da crença dos mortais, reunida por meio de adoração, pactos com servos e atos que inspiram devoção. A Fé alimenta as evocações de seus Saberes e permite revelar sua forma apocalíptica. Um demônio sem Fé é pouco mais que uma voz em um corpo roubado.",
  "wod.fey.boggan": "Os Boggans são fadas caseiras e trabalhadoras, baixinhas e robustas, de mãos habilidosas. Eles sentem verdadeiro prazer no trabalho honesto, como cozinhar, limpar e fazer artesanato, e sempre parecem saber a última fofoca da vizinhança. Os Boggans ajudam de bom grado os humildes e necessitados, mas têm pouca paciência com arrogantes e preguiçosos. Sua fraqueza é a compulsão de terminar toda tarefa que começam e de ajudar quem realmente precisa.",
  "wod.fey.clurichaun": "Os Clurichauns são parentes dos leprechauns do folclore irlandês: brigões joviais que adoram bebida, música e uma boa briga. São charmosos, sortudos e generosos com os amigos, mas se ofendem fácil. Sua sorte lendária e seu faro para tesouros escondidos os ajudam muito. Sua fraqueza é o temperamento explosivo, que torna difícil deixar passar um insulto ou uma discussão.",
  "wod.fey.eshu": "Os Eshu são fadas andarilhas cujas raízes estão nos mitos da África, da Índia e do Oriente Próximo. Eles viajam sem parar em busca de histórias e aventuras, e seu dom os guia até onde algo importante está acontecendo. Os Eshu são contadores de histórias magníficos para quem a hospitalidade é sagrada. Sua fraqueza é a imprudência: quase não conseguem recusar um desafio ou uma aposta arriscada.",
  "wod.fey.ghille": "Os Ghille Dhu são fadas das florestas e de tudo que cresce, aparentadas com os espíritos das árvores e dos lugares selvagens. Seus corpos assumem a aparência de folhas, cascas e trepadeiras e mudam conforme as estações. São guardiões da natureza selvagem, com profunda afinidade com as plantas. Cidades e concreto pesam muito sobre eles, e a maioria evita o mundo urbano.",
  "wod.fey.nocker": "Os Nockers são artesãos e inventores feéricos com um talento genial para construir o impossível a partir de Glamour e sucata. São perfeccionistas que xingam o tempo todo, com criatividade e em voz alta, principalmente o próprio trabalho. Os Nockers consertam e criam maravilhas que nenhum engenheiro mortal conseguiria entender. Sua fraqueza é que tudo o que constroem tem pelo menos um defeito oculto.",
  "wod.fey.pooka": "Os Pookas são fadas brincalhonas que mudam de forma, cada uma ligada a um animal específico, como um gato, uma raposa, um corvo ou um coelho. Elas podem assumir a forma desse animal e compartilham muitos de seus hábitos. Os Pookas são pregadores de peças incorrigíveis, e sua fraqueza marcante é que quase nunca dizem a verdade de forma direta: mentem, exageram ou respondem com charadas. Os amigos aprendem que um carinho sincero costuma se esconder por trás de suas histórias.",
  "wod.fey.redcap": "Os Barretes Vermelhos são os mais temidos entre os plebeus feéricos, fadas de apetite e ameaça que devem o nome aos barretes do folclore que, dizem, eram tingidos de sangue. Eles conseguem morder e engolir quase qualquer coisa, de madeira a metal. Os Barretes Vermelhos adoram intimidar e fazer humor macabro, e as outras fadas evitam contrariá-los. Sua fraqueza é serem tão desagradáveis: pessoas e animais desconfiam deles por instinto.",
  "wod.fey.satyr": "Os Sátiros são fadas da folia e da paixão desenfreada, saídas dos mitos da Grécia antiga, com pernas e chifres de bode. Amam música, vinho, dança e debates filosóficos animados, e suas canções e danças podem despertar a paixão nos outros e afastar a Banalidade por um tempo. Os Sátiros são corredores velozes que desconfiam da moderação e da rotina tediosa. Sua fraqueza é essa mesma paixão: seu humor muda de repente e eles têm dificuldade em resistir à tentação.",
  "wod.fey.selkie": "As Selkies são fadas do mar do folclore das costas do norte, capazes de se transformar em focas com a ajuda de suas peles de foca. Elas sentem um vínculo profundo com o oceano e suas criaturas e muitas vezes protegem a vida marinha. A pele de uma selkie é preciosa: se for perdida ou roubada, ela não consegue mudar de forma e fica muito enfraquecida. Muitas ficam inquietas e saudosas longe do litoral.",
  "wod.fey.sidhe": "Os Sidhe são a nobreza feérica, seres belos e imperiosos que voltaram de Arcádia em 1969 e reivindicaram o governo sobre as demais linhagens. Eles se organizam em casas nobres e lideram a maioria dos feudos e reinos. Sua graça sobrenatural os torna difíceis de ignorar e ainda mais difíceis de recusar. Sua fraqueza é a fragilidade diante da Banalidade, que os atinge com mais força do que às fadas plebeias.",
  "wod.fey.sluagh": "Os Sluagh são fadas pálidas e silenciosas das sombras, dos segredos e dos lugares empoeirados e esquecidos. São especialistas em reunir informações, escutam muito mais do que falam e muitas vezes convivem com fantasmas. Os Sluagh conseguem se espremer por espaços apertados e notam o que os outros deixam passar. Sua fraqueza é que não conseguem falar mais alto que um sussurro.",
  "wod.fey.troll": "Os Trolls são fadas enormes, fortes e firmes, famosas como guardiões e guerreiros leais. Levam juramentos e deveres extremamente a sério, e sua palavra vale como lei. Os Trolls costumam ser quietos e pacientes, mas são terríveis quando se levantam para defender quem protegem. Sua fraqueza é que quebrar um juramento ou abandonar um dever lhes rouba a grande força.",
  "wod.glamour": "O Glamour é a essência dos sonhos e da criatividade, o sangue vital das fadas e do próprio Sonhar. Os changelings o gastam para lançar cantrips, revelar a verdadeira natureza feérica das coisas e sustentar criações quiméricas. Eles o obtêm da inspiração e da arte, do Devaneio compartilhado com mortais e de lugares preciosos chamados feudos. Um changeling privado de Glamour desliza para a Banalidade e o esquecimento.",
  "wod.house.aesin": "A Casa Aesin é uma casa nobre que descende das fadas nórdicas, que afirmam ser aparentadas com os Æsir e os Vanir dos mitos. Em sua maioria unseelie, passaram longas eras no reino gelado de Alfheim antes de voltar ao mundo mortal. Sua sociedade é hierárquica e marcial, guiada por Nove Virtudes como coragem, honra, hospitalidade e autossuficiência. Seus membros conseguem falar com os animais da floresta, mas têm dificuldade em tratar plebeus como iguais.",
  "wod.house.ailil": "A Casa Ailil é a principal casa da Corte Unseelie, famosa pela política, pela intriga e pelas tramas de longo prazo. Seus membros preferem a sutileza e a manipulação ao confronto aberto, e muitos atuam na Corte das Sombras. São diplomatas habilidosos que leem rapidamente as situações e aproveitam cada brecha. Sua fraqueza é o orgulho da própria astúcia, que torna muito difícil para eles admitir um erro.",
  "wod.house.balor": "A Casa Balor é uma casa unseelie que remonta seu sangue aos fomorianos e a Balor do Olho Maligno. Organizada como um exército, considera-se em guerra perpétua contra a ordem seelie e se prepara para um Inverno Sem Fim no qual reinará. Cada membro carrega alguma deformidade do corpo ou do espírito, vista como um desafio a superar. Ao contrário de outros sidhe, eles suportam o contato com o ferro frio sem serem prejudicados.",
  "wod.house.beaumayn": "A Casa Beaumayn é uma casa seelie de profetas, fundada por um cavaleiro profeta na Era Mítica. Todos os seus membros recebem vislumbres de futuros possíveis em sonhos e meditações. Aprisionada em Arcádia após um antigo escândalo e apagada da memória, a casa voltou há pouco tempo e ainda é vista com desconfiança. Suas visões também atraem a atenção da Corte das Sombras e dos Thallain.",
  "wod.house.daireann": "A Casa Daireann é uma antiga casa de guerreiros, curandeiros e campeões celtas que saiu de Arcádia recentemente. Vagamente alinhada à Corte Unseelie, mistura tradições das duas cortes e segue as Três Leis da honra, da vingança e da hospitalidade. Seus guerreiros lutam com uma fúria quase berserker, temperada por um rígido código de honra, e raramente fogem de uma batalha. Sua fraqueza é o gosto por se gabar, que pode soltar a língua e revelar segredos.",
  "wod.house.dougal": "A Casa Dougal é uma casa seelie de mestres ferreiros e artesãos, o centro invisível dos sidhe, que fornece armas, armaduras e invenções às outras casas. O status dentro da casa vem da habilidade e dos feitos, não da política. Muitos de seus membros têm alguma limitação física, muitas vezes compensada por dispositivos que eles mesmos fabricam. Engenharia refinada e máquinas bem-feitas podem cativá-los por horas.",
  "wod.house.eiluned": "A Casa Eiluned é uma casa de feiticeiros, estudiosos e guardiões de segredos, nominalmente seelie, mas à vontade nas zonas cinzentas da moral. Seus membros veem o conhecimento como poder e costumam servir como conselheiros e estrategistas, mais do que como governantes. Seus cantrips são incomumente poderosos. As outras casas desconfiam deles por seu sigilo, e a curiosidade os arrasta o tempo todo para conspirações.",
  "wod.house.fiona": "A Casa Fiona é uma casa seelie de românticos apaixonados e aventureiros destemidos. Seus membros se entregam de corpo e alma ao amor, às missões e às batalhas, e são famosos pela coragem. São calorosos, generosos e leais aos amigos. Sua fraqueza é essa mesma paixão: apaixonam-se fácil e sem pensar, muitas vezes por quem não convém, e raramente recuam diante do perigo.",
  "wod.house.gwydion": "A Casa Gwydion é uma das casas seelie mais poderosas e a casa do Grão-Rei de Concórdia. Seus membros se veem como líderes natos, dedicados à justiça, à honra e à defesa de seus reinos. São juízes perspicazes, difíceis de enganar. Sua fraqueza é um temperamento feroz e uma natureza desconfiada que pode virar fúria quando seu orgulho é ferido.",
  "wod.house.leanhaun": "A Casa Leanhaun é uma casa unseelie de artistas, mecenas e musas que cultivam Sonhadores mortais e extraem deles obras criativas extraordinárias. São carismáticos e graciosos e se destacam como artistas, caçadores de talentos e espiões. Por trás da elegância há uma maldição: precisam continuar colhendo Glamour daqueles que inspiram, ou começam a definhar rapidamente. Muitos apoiam secretamente a Corte das Sombras.",
  "wod.house.liam": "A Casa Liam é uma casa seelie exilada cujo fundador, Lorde Liam, foi banido por defender os mortais com eloquência. Seus membros são sábios, guardiões do saber e contadores de histórias que protegem discretamente os humanos da Banalidade e das fadas predadoras. Eles têm facilidade em tocar os mortais com Glamour. Outras fadas os chamam de quebradores de juramentos e muitas vezes se recusam a honrar seus juramentos ou oferecer-lhes hospitalidade.",
  "wod.house.scathach": "A Casa Scathach foi fundada por Scathach, a lendária mulher guerreira do mito irlandês. Ela se mantém à parte das duas cortes, rejeita o governo hereditário e valoriza o serviço, as viagens e a habilidade marcial. Seus membros, às vezes chamados de Andarilhos Cinzentos, são reservados, silenciosos em combate e de origens mais diversas que outros sidhe. Únicos entre as casas nobres, passaram pelo Caminho Changeling antes da Ruptura, e outros nobres costumam tratá-los com frieza.",
  "wod.house.varich": "A Casa Varich é uma casa unseelie da Rússia, descendente das antigas fadas outrora cultuadas ali, com raízes na Novgorod medieval. É feudal e rigidamente hierárquica e valoriza a lealdade, a estratégia e o trabalho fino em âmbar e ouro. Seus membros conseguem aprender a antecipar os padrões de uma luta ou de uma dança apenas observando. Não podem fazer juramentos de amor e devem aceitar todo desafio que lhes for feito.",
  "wod.lore.awakening": "O Saber do Despertar é um dos Saberes dos Flagelos. Na era da criação ele permitia aos Asharu soprar a centelha da vida em novos corpos e proteger seus protegidos de doenças e ferimentos. No mundo moderno ele permite a um demônio curar feridas, sanar doenças e até devolver a vida a quem acabou de morrer. Com Tormento alto, o mesmo conhecimento pode infligir doença e decomposição.",
  "wod.lore.beasts": "O Saber da Fera é um dos Saberes dos Devoradores. Ele concede domínio sobre animais, peixes e aves, permitindo a um demônio invocá-los, comandá-los e até remodelar seus corpos. Os Rabisu o usaram um dia para pastorear todas as criaturas selvagens. Ele também permite a um demônio tocar os instintos primitivos que os humanos compartilham com os animais.",
  "wod.lore.celestials": "O Saber dos Celestiais é um dos Saberes dos Diabos. No Céu ele permitia aos Namaru localizar, informar e apoiar outros anjos; agora ele se alimenta da fé dos mortais. Um demônio que o conhece pode sentir a presença de outros seres espirituais, falar à distância e invocar o poder dos nomes divinos. É um saber de comunicação, autoridade e poder sagrado.",
  "wod.lore.death": "O Saber da Morte é um dos Saberes dos Ceifadores. Originalmente ele permitia aos Halaku encerrar a vida de forma rápida e indolor e decompor a matéria morta para que a criação pudesse recomeçar. Nas mãos de um demônio ele acelera a decomposição, faz murchar os seres vivos e traz a morte. Reflete o dever da casa de encerrar o que cumpriu seu ciclo.",
  "wod.lore.earth": "O Saber da Terra é um dos Saberes dos Malfeitores. Ele guarda os segredos de moldar a rocha e o solo, de mover uma única pedra a transformar a paisagem. Os Annunaki o usaram um dia para formar e manter a face do Paraíso. Um demônio com este saber pode atravessar a pedra, erguer muralhas de terra ou fazer o próprio chão tremer.",
  "wod.lore.firmament": "O Saber do Firmamento é um dos Saberes dos Flagelos. Ele restaura parte da ampla percepção que os Asharu já tiveram, permitindo sentir quando aqueles sob seus cuidados sofrem ou correm perigo. Um demônio que o conhece pode perceber lugares e acontecimentos distantes e alcançar grandes distâncias. É um saber de vigilância e proteção.",
  "wod.lore.flame": "O Saber da Chama é um dos Saberes dos Diabos. Ele concede domínio sobre o fogo primordial e purificador da criação, de acender uma vela a provocar um incêndio. Durante a guerra tornou-se uma das principais armas dos Namaru. Um demônio que o conhece pode invocar, controlar e moldar o fogo, e se proteger dele.",
  "wod.lore.flesh": "O Saber da Carne é um dos Saberes dos Devoradores. Ele surgiu durante a guerra contra o Céu, quando os Rabisu aprenderam a remodelar corpos vivos para a batalha. Com ele, um demônio pode esculpir a carne, desenvolver armas naturais, curar ou deformar tecidos vivos e fortalecer o corpo. É um dos Saberes mais viscerais e temidos.",
  "wod.lore.forge": "O Saber da Forja é um dos Saberes dos Malfeitores. É o lado prático de seu poder criador, o conhecimento para fabricar ferramentas, armas e objetos de qualidade prodigiosa. Um demônio com este saber pode consertar ou destruir objetos e encantá-los com poder duradouro. Muitos dos artefatos mais perigosos da guerra foram criados com ele.",
  "wod.lore.light": "O Saber da Luz é um dos Saberes dos Malignos. Ele abrange a natureza da luz e da percepção, e os Neberu aprenderam a dobrá-la em ilusões poderosas. Um demônio que o conhece pode se envolver em sombras, ofuscar inimigos e tecer imagens convincentes que enganam os sentidos. Tornou-se uma arma essencial no arsenal de despistes dos Malignos.",
  "wod.lore.longing": "O Saber do Anseio é um dos Saberes dos Profanadores, a sabedoria central de sua casa. Ele concede o poder de tocar o coração humano, despertando desejo, esperança, tristeza ou inspiração. Os Lammasu o usaram um dia para elevar a humanidade rumo à verdade e à beleza. Depois da Queda, ele é usado com a mesma frequência para tentar e manipular.",
  "wod.lore.paths": "O Saber dos Caminhos é um dos Saberes dos Malfeitores. Ele rege como um objeto físico viaja de um ponto a outro: as estradas e rotas do mundo material. Um demônio que o conhece sempre encontra o caminho, pode selar ou abrir passagens e acelerar ou atrapalhar o movimento. É a arte silenciosa da jornada.",
  "wod.lore.patterns": "O Saber dos Padrões é um dos Saberes dos Malignos. Ele permite a um demônio estudar os movimentos do Grande Projeto e prever problemas antes que aconteçam. Com ele, os Neberu podem ler probabilidades, vislumbrar o que pode vir e empurrar sutilmente o acaso e o destino. É o saber da profecia e do destino.",
  "wod.lore.portals": "O Saber dos Portais é um dos Saberes dos Malignos. Ele guarda os segredos de atravessar a realidade num instante, abrindo portas entre lugares distantes. Um demônio que o conhece pode trancar e destrancar passagens, perceber rotas através do espaço e viajar sem percorrer a distância entre os pontos. Na criação, ele permitia aos Neberu se mover livremente pelo cosmos de que cuidavam.",
  "wod.lore.radiance": "O Saber do Esplendor é um dos Saberes dos Diabos. Ele guarda os segredos da inspiração e da liderança, e na Era da Ira os Namaru o desenvolveram para inflamar seus aliados mortais. Um demônio que o conhece pode projetar uma aura de majestade, reunir seguidores, inspirar admiração ou terror e prender a atenção de todos. É o saber da presença e do comando.",
  "wod.lore.realms": "O Saber dos Reinos é um dos Saberes dos Ceifadores. Ele trata das fronteiras entre o mundo físico e os bolsões de realidade além dele. Os Halaku o usaram para estabilizar reinos fora do cosmos e viajar até eles, e ele lançou as bases das Terras das Sombras dos mortos. Um demônio que o conhece pode perceber e cruzar as fronteiras entre mundos.",
  "wod.lore.spirit": "O Saber do Espírito é um dos Saberes dos Ceifadores. Ele trata das almas dos mortos, e com ele os Halaku podiam ancorar espíritos a lugares da Terra para que não se perdessem. Um demônio que o conhece pode ver fantasmas e falar com eles, comandá-los ou prendê-los. É o saber dos mortos inquietos.",
  "wod.lore.storms": "O Saber das Tempestades é um dos Saberes dos Profanadores. Ele concede domínio sobre o vento e as ondas, de acalmar as águas a erguer tempestades. Com ele, os Lammasu estenderam sua influência dos mares até a terra firme. Um demônio que o conhece pode chamar a chuva, comandar a água e liberar a fúria do clima.",
  "wod.lore.transfiguration": "O Saber da Transfiguração é um dos Saberes dos Profanadores. Ele permite a um demônio mudar de aparência à vontade para corresponder ao que os outros esperam ou desejam. Abrange máscaras, disfarces e a remodelação da própria forma. Nas mãos dos Lammasu, é um saber de sedução e engano tanto quanto de beleza.",
  "wod.lore.wild": "O Saber do Selvagem é um dos Saberes dos Devoradores. Ele reúne os segredos das florestas e dos campos, permitindo a um demônio comandar plantas e moldar ambientes naturais. Os Rabisu cuidavam com ele de tudo o que cresce no mundo. Um demônio que o conhece pode fazer plantas crescerem, murcharem ou se moverem e voltar a própria natureza selvagem contra intrusos.",
  "wod.lore.winds": "O Saber dos Ventos é um dos Saberes dos Flagelos. Ele rege as correntes de ar que sustentam a vida, de um sopro suave a um vendaval uivante. Os Asharu o usaram um dia para espalhar o sopro da vida pelo mundo. Um demônio que o conhece pode comandar o vento, levar vozes e cheiros, e proteger ou negar o próprio ar que os outros respiram.",
  "wod.seem.grump": "Rabugento é a aparência de um changeling mais velho, a última etapa de uma vida mortal vivida ao lado de uma alma feérica. Os Rabugentos estão mais perto da Banalidade e têm menos Glamour, mas carregam longa experiência, profundo conhecimento do saber feérico e uma língua afiada. Muitas vezes são guardiões da tradição e mestres de cantrips, conhecidos por reclamar, mas valorizados pela sabedoria. Muitos changelings mais jovens aprendem a enxergar o carinho por trás do mau humor.",
  "wod.seem.wilder": "Rebelde é a aparência de um changeling jovem adulto cuja alma feérica ainda arde com força. Os Rebeldes são cheios de energia, paixão e rebeldia, ansiosos para viver tudo e se testar diante do mundo. Eles buscam o próprio caminho e se dividem entre seus lados seelie e unseelie. Os Rebeldes formam a maioria dos changelings aventureiros, embora sua impetuosidade muitas vezes os meta em encrencas.",
  "leg.l.al": "A XX Legião, liderada pelo Primarca Alpharius, o último dos Primarcas a ser encontrado. A Legião Alfa lutava por meio de infiltração, despistes e enganos em várias camadas, com agentes e células escondidos entre os inimigos, e adotou como emblema a hidra de muitas cabeças. Ficou do lado de Horus na Heresia, embora seus verdadeiros motivos continuem sendo um mistério.",
  "leg.l.ba": "A IX Legião, liderada pelo Primarca alado Sanguinius, cujos filhos eram recrutados em Baal, um mundo marcado pela radiação. Os Anjos Sangrentos são guerreiros nobres e grandes artistas, mas sua semente genética esconde uma maldição: a Sede Vermelha e a Fúria Negra. Permaneceram leais, e Sanguinius caiu lutando contra Horus a bordo da nau capitânia do Senhor da Guerra durante o Cerco de Terra.",
  "leg.l.da": "A I Legião, a primeira a ser criada, liderada pelo Primarca Lion El'Jonson, do mundo florestal de Caliban. Os Anjos Sombrios dominavam todas as formas de guerra e guardavam muitas armas e ordens secretas. Permaneceram leais, mas parte da Legião se voltou contra o Leão e Caliban foi destruído; a caçada a esses Caídos é desde então sua vergonha oculta.",
  "leg.l.dg": "A XIV Legião, liderada pelo Primarca Mortarion, criado em Barbarus, um mundo sufocado por venenos. A Guarda da Morte valorizava a resistência sombria, a imunidade a toxinas e o avanço implacável. Juntou-se a Horus e, presa na Disformidade, foi atingida por uma praga terrível que a transformou nos inchados e incansáveis Fuzileiros da Praga de Nurgle.",
  "leg.l.ec": "A III Legião, liderada pelo Primarca Fulgrim e reconstruída quase a partir da extinção no mundo de Chemos. Os Filhos do Imperador eram obcecados pela perfeição e receberam a honra de portar a própria águia do Imperador. O orgulho os levou ao deus do Caos Slaanesh, e como traidores abandonaram todos os limites em busca do excesso e da sensação.",
  "leg.l.if": "A VII Legião, liderada pelo Primarca Rogal Dorn, famosa como a melhor construtora e defensora de fortificações. Os Punhos Imperiais eram firmes e inflexíveis, e sua casa era a nave-fortaleza Phalanx. Leais ao Imperador, fortificaram o Palácio Imperial e o defenderam contra os traidores durante o Cerco de Terra.",
  "leg.l.ih": "A X Legião, liderada pelo Primarca Ferrus Manus, do duro mundo de Medusa. As Mãos de Ferro acreditam que \"a carne é fraca\", substituem o corpo por biônicos e valorizam a lógica fria acima das emoções. Leais ao Imperador, perderam seu Primarca no Massacre da Zona de Desembarque em Isstvan V, onde Ferrus Manus foi morto por Fulgrim.",
  "leg.l.iw": "A IV Legião, liderada pelo Primarca Perturabo, de Olympia, mestres do cerco e da guerra de desgaste. Aos Guerreiros de Ferro cabiam sempre os cercos exaustivos e ingratos da Grande Cruzada, e sua amargura crescia a cada campanha. Juntaram-se a Horus, e seu lema é \"Ferro por dentro, ferro por fora\".",
  "leg.l.nl": "A VIII Legião, liderada pelo Primarca Konrad Curze, o Assombrador Noturno, do mundo sem luz de Nostramo. Os Senhores da Noite guerreavam pelo terror, quebrando mundos inteiros pelo medo antes e durante a batalha. Tornaram-se traidores, e Curze, atormentado por visões da própria morte, permitiu que uma assassina imperial o matasse.",
  "leg.l.rg": "A XIX Legião, liderada pelo Primarca Corvus Corax, que libertou a lua-prisão de Libertação. A Guarda Corvo é especialista em furtividade, velocidade e ataques precisos a partir das sombras. Leal ao Imperador, foi quase destruída no Massacre da Zona de Desembarque em Isstvan V, mas resistiu e se reconstruiu.",
  "leg.l.sal": "A XVIII Legião, liderada pelo Primarca Vulkan, do mundo vulcânico de Nocturne. Os Salamandras são mestres ferreiros que forjam as próprias armas, preferem lança-chamas e armas de fusão e são conhecidos por proteger as pessoas comuns. Permaneceram leais e sofreram terrivelmente em Isstvan V.",
  "leg.l.soh": "A XVI Legião, originalmente os Lobos Lunares, rebatizada em honra de seu Primarca Horus Lupercal quando ele se tornou Senhor da Guerra. Os Filhos de Hórus foram a principal Legião do Imperador até Horus se voltar para o Caos e liderar a rebelião que ficou conhecida como a Heresia de Horus. Após sua morte, a Legião passou a se chamar Legião Negra sob o comando de Abaddon.",
  "leg.l.sw": "A VI Legião, liderada pelo Primarca Leman Russ, do mundo gelado de Fenris. Os Lobos Espaciais são guerreiros ferozes e selvagens, com tradições próprias e Sacerdotes Rúnicos, e serviam como os carrascos do Imperador. Leais, foram enviados contra Magnus, o Vermelho, e seu ataque destruiu Próspero, o mundo natal dos Mil Filhos.",
  "leg.l.ts": "A XV Legião, liderada pelo Primarca psíquico Magnus, o Vermelho, de Próspero, os estudiosos e feiticeiros mais sábios entre as Legiões. Os Mil Filhos sofriam com mutações, e sua dependência do poder psíquico os tornava suspeitos. Após o incêndio de Próspero, juntaram-se a Horus e a Tzeentch; mais tarde, a Rubrica do feiticeiro Ahriman transformou a maioria deles em pó dentro de armaduras seladas.",
  "leg.l.um": "A XIII Legião, liderada pelo Primarca Roboute Guilliman, governante de Macragge e do reino de Ultramar. Os Ultramarines eram a maior Legião, famosa pela disciplina, logística e ordem. Permaneceram leais e, depois da Heresia, Guilliman escreveu o Codex Astartes, que dividiu as Legiões em Capítulos e ainda orienta a maioria dos Fuzileiros Espaciais.",
  "leg.l.wb": "A XVII Legião, liderada pelo Primarca Lorgar, de Colchis, que adorava o Imperador como um deus. Depois que o Imperador os repreendeu em Monarchia, os Portadores da Palavra se voltaram em segredo para os deuses do Caos. Foram a primeira Legião a cair diante do Caos e ajudaram a arrastar Horus para a rebelião.",
  "leg.l.we": "A XII Legião, antes chamada de Cães de Guerra, liderada pelo Primarca Angron, um ex-gladiador. Angron obrigou seus guerreiros a receber os Pregos do Açougueiro, implantes que inundam o cérebro de fúria, e os Devoradores de Mundos se tornaram a mais selvagem das Legiões. Juntaram-se a Horus e se entregaram por completo a Khorne.",
  "leg.l.ws": "A V Legião, liderada pelo Primarca Jaghatai Khan, do mundo das estepes de Chogoris. As Cicatrizes Brancas são mestres da guerra relâmpago: ataques velozes, investidas montadas e perseguição implacável. Permaneceram leais, abriram caminho de volta a Terra e ajudaram a defender o Palácio Imperial durante o Cerco.",
  "leg.lost": "A Segunda e a Décima Primeira Legião não aparecem em nenhum registro imperial. Algo aconteceu com elas e com seus Primarcas durante a Grande Cruzada, e seus nomes e histórias foram apagados de propósito. Quem conhece a verdade é obrigado a guardar silêncio, e nada confiável se sabe sobre seu destino.",
  "ow.grudges": "O Dammaz Kron, o Grande Livro dos Rancores, fica sob a guarda do Grande Rei dos Anões em Karaz-a-Karak e registra cada ofensa já cometida contra o povo anão. Por tradição, os registros são escritos com o sangue do Grande Rei. Um rancor só é riscado depois de vingado, e cada fortaleza, clã e família também mantém seu próprio livro.",
  "ow.r.beast": "Os Homens-Fera são filhos do Caos com chifres e cabeça de bode que espreitam nas florestas profundas do Velho Mundo. Reúnem-se em manadas ao redor de pedras sagradas e odeiam a civilização, atacando vilas e cidades para derrubar o que os humanos construíram. Gors, ungors, minotauros e monstros lutam juntos sob o comando de um senhor das feras.",
  "ow.r.bret": "A Bretônia é um reino de cavaleiros, governado por um rei e devotado à Dama do Lago. Sua nobreza vive segundo um código de cavalaria, enquanto os camponeses a servem. Os maiores cavaleiros partem em busca do Graal; os que conseguem se tornam Cavaleiros do Graal, e o poder do reino se apoia nas cargas da cavalaria pesada.",
  "ow.r.cathay": "O Grande Catai é um vasto império do extremo oriente, governado pelo Imperador Dragão e seus filhos, dragões antigos capazes de assumir forma humana. Seus exércitos guardam o Grande Bastião, uma enorme muralha que detém as forças do Caos vindas do norte. Catai valoriza a harmonia e a ordem, e suas mercadorias chegam ao Velho Mundo pela Rota do Marfim.",
  "ow.r.cd": "Os Anões do Caos descendem de anões que ficaram isolados nas Terras Sombrias e passaram a cultuar Hashut, o Pai das Trevas com cabeça de touro. De sua grande cidade-zigurate governam um reino industrial construído sobre trabalho escravo, feitiçaria e máquinas de guerra com demônios aprisionados. Seus feiticeiros têm grande poder, mas lentamente se transformam em pedra.",
  "ow.r.de": "Os Elfos Negros são um povo cruel e exilado da fria terra de Naggaroth, governado pelo Rei Bruxo Malekith. Adoram Khaine, o deus do assassinato, e de suas arcas negras lançam ataques pelo mundo todo em busca de cativos e tesouros. Seu ódio pelos parentes, os Altos Elfos, não tem fim.",
  "ow.r.dwarf": "Os Anões são um povo orgulhoso e teimoso de antigas fortalezas nas montanhas, a maior das quais é Karaz-a-Karak. São excelentes mineiros, ferreiros e engenheiros, honram seus deuses ancestrais, e seus Ferreiros Rúnicos prendem magia em runas. Nunca esquecem uma ofensa, e seu império, embora enfraquecido, continua lutando contra orcs, goblins e skaven.",
  "ow.r.emp": "O Império é o maior e mais poderoso reino humano do Velho Mundo, fundado por Sigmar, que hoje é adorado como um deus. É governado por um Imperador escolhido pelos Condes Eleitores de suas províncias. Seus exércitos combinam tropas estatais, cavaleiros, magos de batalha dos Colégios de Magia, artilharia a pólvora e tanques a vapor.",
  "ow.r.he": "Os Altos Elfos são um povo antigo e orgulhoso da ilha de Ulthuan, governado pelo Rei Fênix e pela Rainha Eterna. São mestres da magia e do mar e mantêm o Grande Vórtice, que drena o poder bruto do Caos. Seus exércitos disciplinados de lanceiros, arqueiros e guerreiros de elite lutam para proteger o mundo contra o Caos.",
  "ow.r.kislev": "Kislev é um reino humano do norte, de estepes e florestas, que fica entre o Velho Mundo e os Ermos do Caos. É governado por um czar ou uma czarina, e seus soberanos muitas vezes dominaram uma poderosa magia de gelo. Os kislevitas são resistentes e ferozmente independentes, e seus exércitos de lanceiros alados, arqueiros montados e infantaria obstinada contêm as invasões vindas do norte.",
  "ow.r.liz": "Os Homens-Lagarto são os servos dos Antigos e vivem nas selvas úmidas e nas cidades-templo de Lustria. São liderados pelos slann, antigos magos-sacerdotes de imenso poder, e lutam com guerreiros sáurios, skinks e grandes feras reptilianas. Seu propósito é cumprir o Grande Plano de seus criadores desaparecidos.",
  "ow.r.ogre": "Os Ogros são brutamontes enormes e sempre famintos das Montanhas do Luto que adoram a Grande Bocarra, um deus de fome sem fim. Suas tribos são governadas pelo Tirano mais forte, e qualquer coisa pode acabar em suas barrigas. Muitos viajam pelo mundo como mercenários, valorizados por sua força e pela disposição de lutar por pagamento ou comida.",
  "ow.r.orc": "Os Orcs e Goblins são peles-verdes, uma raça resistente e numerosa que vive para lutar. Adoram Gork e Mork, e quando surge um chefe guerreiro forte, as tribos se reúnem em um grande Waaagh! que varre a terra. Orcs grandes e brutais e goblins sorrateiros, junto com trolls e gigantes, formam hordas enormes e indisciplinadas.",
  "ow.r.skaven": "Os Skaven são homens-rato que vivem em um vasto Império Subterrâneo escavado sob o mundo, com capital em Skavenblight. Adoram o Rato Chifrudo e são governados pelo Conselho dos Treze, enquanto clãs rivais tramam uns contra os outros. Com pedra-bruxa, pragas e máquinas estranhas, planejam dominar a superfície, embora a maioria dos humanos pense que eles são um mito.",
  "ow.r.tk": "Os Reis Funerários são os antigos governantes de Nehekhara, uma terra desértica de grandes pirâmides, erguidos da morte pelo terrível ritual de Nagash. Presos aos próprios corpos, comandam legiões de guerreiros esqueletos e constructos animados, enquanto os Sacerdotes Funerários realizam os ritos. Buscam restaurar a glória perdida de seus reinos.",
  "ow.r.vamp": "Os Vampiros são nobres imortais que governam os mortos, mais infamemente na terra amaldiçoada da Sylvania. Por meio da necromancia, erguem exércitos de zumbis, esqueletos e carniçais para servi-los. Suas linhagens, como os von Carstein, ameaçaram o Império repetidas vezes.",
  "ow.r.we": "Os Elfos Silvestres são os guardiões de Athel Loren, uma floresta encantada do Velho Mundo. Vivem em harmonia com seus espíritos e servem aos soberanos da floresta, Orion e Ariel. São arqueiros sem igual que atacam rapidamente a partir das árvores, defendendo seu reino de qualquer invasor.",
  "ow.r.woc": "Os Guerreiros do Caos são campeões mortais do norte gelado que servem aos deuses do Caos em busca de glória e favor. Vestidos com armaduras pesadas e muitas vezes portando dons de mutação, lideram grandes invasões ao sul contra as terras civilizadas. Os mais favorecidos podem ascender à condição de demônio; os que fracassam podem virar crias sem mente.",
  "wh.f.aeldari": "Os Aeldari são uma raça antiga com grandes dons psíquicos, cujo grande império ruiu na Queda, quando seus próprios excessos deram origem ao deus do Caos Slaanesh. Os sobreviventes vivem em enormes mundos-nave e seguem Caminhos rigorosos para controlar sua natureza. Lutam com tecnologia elegante e psíquicos poderosos, e preservam suas almas em pedras espirituais.",
  "wh.f.csm": "Os Fuzileiros Espaciais do Caos são Fuzileiros Espaciais renegados que se voltaram contra o Imperium e servem aos Poderes Ruinosos. Muitos são veteranos das Legiões Traidoras que fugiram para o Olho do Terror após a Heresia de Horus e desde então travam a Longa Guerra. Lutam com equipamentos antigos, demônios e mutações concedidas por seus deuses.",
  "wh.f.dmech": "O Mechanicum Sombrio é formado pelos tecnossacerdotes de Marte que ficaram do lado de Horus e abraçaram o Caos. Buscam sem limites o conhecimento e a tecnologia proibidos, prendendo demônios em máquinas e criando engenhos demoníacos. Suas criações servem às forças traidoras até hoje.",
  "wh.f.drukhari": "Os Drukhari são os parentes cruéis dos Aeldari e vivem em Commorragh, uma cidade sombria escondida na Teia. Para adiar a reivindicação de Slaanesh sobre suas almas, sustentam-se infligindo sofrimento a outros. Lançam ataques rápidos ao espaço real para capturar prisioneiros, usando veículos flutuantes velozes e lâminas mortais.",
  "wh.f.gk": "Os Cavaleiros Cinzentos são um Capítulo secreto de Fuzileiros Espaciais, formado inteiramente por psíquicos e dedicado a combater demônios. Servem ao Ordo Malleus da Inquisição a partir de sua fortaleza em Titã. Armados com armas de força Nêmesis e protegidos por armaduras abençoadas, estão entre os guerreiros mais incorruptíveis do Imperium.",
  "wh.f.harlequins": "Os Arlequins são misteriosos guerreiros-artistas Aeldari devotados a Cegorach, o Deus Risonho. Viajam pela Teia em trupes, encenando mitos sagrados e entrando em batalha com graça acrobática. Também são os guardiões da Biblioteca Negra, um acervo oculto de conhecimento proibido.",
  "wh.f.ig": "A Guarda Imperial, também chamada de Astra Militarum, é o vasto exército do Imperium, formado por incontáveis regimentos recrutados em mundos de toda a galáxia. Seus soldados são humanos comuns armados com armas laser e apoiados por tanques e artilharia. O que lhes falta em força, compensam com números, coragem e sacrifício sem fim.",
  "wh.f.mech": "O Adeptus Mechanicus é o sacerdócio de Marte, que adora o Deus-Máquina, também chamado de Omnissiah. Seus tecnossacerdotes preservam e mantêm a tecnologia do Imperium, guardam conhecimentos antigos e substituem a própria carne por máquinas. Coloca em campo exércitos de skitarii, servidores e máquinas de guerra.",
  "wh.f.necrons": "Os Necrons são uma raça antiga cujos corpos vivos foram transferidos para formas de metal imperecível em um pacto com os deuses estelares chamados C'tan. Depois de dormir milhões de anos em seus mundos-tumba, estão despertando para retomar a galáxia. Lutam com armas gauss e tecnologia aterradora, e seus corpos se reparam sozinhos.",
  "wh.f.orks": "Os Orks são uma raça de pele verde que vive para a guerra e está espalhada por toda a galáxia. São duros e resistentes, e sua tecnologia tosca muitas vezes só funciona porque eles acreditam que funciona. Quando Orks suficientes se reúnem sob um chefe forte, eles lançam uma WAAAGH!",
  "wh.f.sm": "Os Fuzileiros Espaciais, também chamados de Adeptus Astartes, são guerreiros geneticamente aprimorados do Imperium. Organizados em Capítulos de cerca de mil guerreiros, são os Anjos da Morte do Imperador, enviados aos campos de batalha mais perigosos. Vestindo armadura energizada e armados com bolters, são os melhores soldados do Imperium.",
  "wh.f.sob": "As Irmãs de Batalha, também conhecidas como Adepta Sororitas, são as ordens militares da Eclesiarquia, a igreja imperial. Lutam com fé inabalável no Imperador, armadas com bolters, lança-chamas e armas de fusão. Sua fé é tão forte que às vezes se manifesta como milagres no campo de batalha.",
  "wh.f.tau": "Os T'au são uma raça jovem e tecnologicamente avançada da Orla Oriental da galáxia, unida pela filosofia do Bem Maior. Sua sociedade é dividida em castas e liderada pelos misteriosos Etéreos. Seus exércitos dependem de trajes de batalha e poderosas armas de pulso, e muitas vezes procuram incorporar outras raças de forma pacífica.",
  "wh.f.tyranids": "Os Tirânidos são um enxame vindo de fora da galáxia e guiado por uma única Mente Colmeia. Suas frotas-colmeia viajam entre as estrelas, consumindo toda a matéria biológica dos mundos que invadem para criar novas criaturas. Adaptam-se rapidamente a qualquer defesa e já devoraram incontáveis mundos.",
  "wh.waaagh": "Uma WAAAGH! é ao mesmo tempo uma grande cruzada ork e o poder psíquico gerado pelos Orks quando se reúnem em grande número. Quando um chefe junta seguidores suficientes, a WAAAGH fica mais barulhenta e mais forte, atraindo ainda mais Orks. Quanto maior a WAAAGH, mais poderosos os Orks se tornam.",
  "wr.mut": "Mutações são os dons dos deuses do Caos, marcas de favor que deformam o corpo de seus seguidores. Podem ir de olhos ou membros extras a presas, chifres ou tentáculos. Para um campeão do Caos, as mutações são sinais de favor que podem levar à condição de demônio, mas mutações demais podem transformá-lo em uma cria sem mente.",
  "wr.of.khorne": "Khorne é o Deus do Sangue, o deus do Caos da guerra, da fúria e da força marcial, que se senta em um trono de crânios. Servir a Khorne é lutar sem fim, colhendo crânios em seu nome e desprezando a feitiçaria e a covardia. Seus seguidores acreditam que há honra no combate.",
  "wr.of.nurgle": "Nurgle é o Deus da Praga, também chamado de Vovô Nurgle, o deus do Caos da doença e da decadência, mas também da resistência e do renascimento. Seus seguidores são abençoados com doenças que os tornam imunes à dor e ao desespero. Servir a Nurgle é abraçar o ciclo da vida e da morte.",
  "wr.of.rat": "O Rato Chifrudo é o deus dos Skaven, às vezes adorado como um quinto deus do Caos. Seus seguidores são tramadores, ambiciosos e traiçoeiros, sempre procurando a quem trair. Servir ao Rato Chifrudo é conspirar para que os Skaven governem o mundo.",
  "wr.of.slaanesh": "Slaanesh é o Príncipe Sombrio, o deus do Caos do excesso, da perfeição e da sensação. Seus seguidores buscam a perfeição em tudo e vão cada vez mais longe em busca de novas experiências. Servir a Slaanesh é nunca estar satisfeito.",
  "wr.of.tzeentch": "Tzeentch é o Arquiteto da Mudança, o deus do Caos da mudança, da ambição e da feitiçaria. Seus seguidores são feiticeiros ardilosos que buscam conhecimento e poder. Servir a Tzeentch é tornar-se parte de seus planos sem fim.",
  "rz.s.pride": "O Orgulho é o pecado de quem se coloca acima de todos. Em Re:Zero, seu Fator de Bruxa concede uma Autoridade que transforma a culpa em arma: quem se sente culpado diante do portador é despedaçado por essa mesma culpa. Hoje não se sabe quem porta o Fator de Bruxa do Orgulho.",
  "rz.s.greed": "A Ganância é querer tudo e não abrir mão de nada. Suas Autoridades param o tempo: o portador pode congelar o tempo do próprio corpo e de tudo o que veste, e nada consegue tocá-lo. O Pequeno Rei liga esse poder ao coração de outros, e Cor Leonis permite ao portador carregar o fardo dos companheiros enquanto os torna mais fortes.",
  "rz.s.envy": "A Inveja é desejar o que os outros têm. O poder da sua Bruxa é a sombra: uma escuridão que se estende, engole e não solta. É o mais temido dos sete pecados — o mundo ainda lembra a sua Bruxa como aquela que engoliu metade dele.",
  "rz.s.wrath": "A Ira é sentir tudo de uma vez e fazer os outros sentirem também. Sua Autoridade espalha as emoções do portador para todos ao redor até que todos compartilhem um só sentimento, dor incluída. O portador também comanda correntes e pode transformá-las em fogo.",
  "rz.s.sloth": "A Preguiça é o pecado de não fazer nada — e da loucura por trás disso. Sua Autoridade lança uma onda negra que turva a mente de quem está perto e concede a Mão Invisível: mãos que ninguém vê e que trabalham pelo portador, erguendo, segurando e esmagando à distância.",
  "rz.s.lust": "A Luxúria é o desejo de ser desejado. Sua Autoridade, Variação e Mudança, remodela corpos: o portador pode assumir qualquer forma, dar novas formas a outros e até curar feridas remodelando a carne.",
  "rz.s.gluttony": "A Gula é uma fome que nunca se satisfaz. Sua Autoridade devora o nome e as memórias de uma pessoa, e o mundo a esquece. O seu Eclipse permite a quem devora usar as habilidades dos devorados ou assumir a aparência deles.",
  "rz.r.follower": "Um seguidor é um dos muitos membros do Culto da Bruxa que servem a um pecado. Ele não porta nenhum Fator de Bruxa: seu único poder é a fé.",
  "rz.r.archbishop": "Um Arcebispo do Pecado é um dos líderes do Culto da Bruxa. Cada arcebispo porta o Fator de Bruxa do seu pecado e exerce a sua Autoridade.",
  "rz.r.witch": "A Bruxa é aquela em quem o pecado tomou forma pela primeira vez. As Bruxas dos sete pecados viveram há muito tempo; seus Fatores de Bruxa sobreviveram a elas e ainda passam de portador em portador.",
});
